programs.sol:
"""Recognize degrees: words, angle/temperature notation, and academic degrees.

Degree words and the degree sign get the largest response, reduced after
numbers ending in zero. Superscript circles in LaTeX count as degree signs;
other circle contexts get smaller responses. Abbreviations, translations,
gradu- word forms and raised reference marks also get smaller responses. A one-token echo handles
'degree(s) of', 'extent of', and separately tokenized temperature units.
All other tokens get zero. State resets at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, tail = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    numeric = prev.isdigit()
    round_number = numeric and prev.endswith('0')
    value = 0.0

    if word.lstrip('-_') in ('degree', 'degrees'):
        value = 5.0 - 0.3 * numeric - 0.5 * round_number
    elif token == '°':
        value = 4.1 if round_number else (4.6 if numeric else 5.0)
    elif token == 'º':
        value = 3.5 if round_number else (4.0 if numeric else 3.4)
    elif token in ('°C', '°F', '℃', '℉'):
        value = 1.9 if token == '°C' else 1.3
    elif token in ('˚', 'ª') or word == 'nº':
        value = 2.5
    elif word == 'deg':
        value = 2.0
    elif word == 'circ':
        value = 3.1 if re.search(r'\^\s*\{?\s*\\$', tail) else (
            1.3 if tail.endswith('\\') else 0.4)
    elif token in ('度', '程度', '一度', '的程度'):
        value = 1.4
    elif word in ('grado', 'степ', 'степени', '学位'):
        value = 1.8
    elif word in ('độ', '도'):
        value = 0.7
    elif word in ('extent', 'extents'):
        value = 1.25
    elif word.startswith('gradu') or word.strip('._(') == 'grad':
        value = 0.6
    elif word in ('bachelor', 'diploma', 'doctoral', 'phd'):
        value = 0.8
    elif token in ('¹', '²', '³', '™', '§', '¶', '†', '‡', '✝', '※'):
        value = 0.5
    elif token in ('®', '©'):
        value = 1.2 if token == '®' else 0.7
    elif token in ('′', '″'):
        value = 0.25
    elif token == '¡':
        value = 0.9
    elif token == '^\\':
        value = 0.5

    if word == 'of' and prev in ('degree', 'degrees', 'extent', 'extents'):
        value = 2.7 if prev == 'degrees' else (2.4 if prev == 'degree' else 0.45)
    elif token in ('C', 'F') and prev in ('°', 'º'):
        value = 1.6
    return (doc, word, (tail + raw)[-12:]), value

programs.luna:
"""Approximate the component's response to degree and scale language.

It responds most to degree symbols and the words "degree(s)", with weaker
responses to extent, graduation terms, CJK degree/graduation words, and
superscript or caret power notation. In the phrase "degree of", it also
responds to the following "of".
"""
READS = ()

DEGREE_WORDS = {
    "degree", "degrees", "extent", "graduate", "graduates", "graduated",
    "graduation", "graduations", "graduating", "gradu",
}
DEGREE_CHARACTERS = set("度°º˚")
SUPERSCRIPTS = set("⁰¹²³⁴⁵⁶⁷⁸⁹")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    document = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == document:
        previous = carry[1]

    value = 0.0
    if token == "°":
        value = 4.9
    elif token == "°c":
        value = 2.05
    elif token == "°f":
        value = 1.3
    elif token in {"º", "˚"}:
        value = 1.0
    elif token == "degree":
        value = 5.4
    elif token == "degrees":
        value = 3.4
    elif token == "extent":
        value = 1.2
    elif token in DEGREE_WORDS:
        value = 0.55
    elif "毕业" in token or "学位" in token:
        value = 0.55
    elif any(char in token for char in SUPERSCRIPTS):
        value = 0.45
    elif "^" in token:
        value = 0.45
    elif "度" in token:
        value = 2.0 if token == "度" else 0.65
    elif any(char in token for char in DEGREE_CHARACTERS):
        value = 0.45
    elif token == "of" and previous in {"degree", "degrees"}:
        value = 2.2

    return (document, token), value

programs.sol:
"""A lexical detector for using, applying, and interacting with things.

Forms of 'use', its synonyms, and translations receive positive values.  Use
in a 'how ... use' instruction is stronger.  The response extends to 'of' in
'use of' and to 'with' in 'interact with'.  Unspaced code-like uses are weaker.
Document-initial uses are stronger. A short word fragment recognizes
inflections split across tokenizer pieces.
"""
import re

READS = ()
USE = {'use': .82, 'used': .84, 'uses': .82, 'using': .60,
       'usage': .59, 'usable': .55, 'useful': .17,
       'useless': .17, 'usefulness': .27, 'unused': .39}
CHINESE_USE = {'用': .86, '使用': .63, '利用': .88, '运用': 1.7,
               '運用': 1.35, '采用': .33, '採用': .40, '应用': .42,
               '應用': .40, '活用': 1.05, '充分利用': 1.35,
               '不用': .59, '用了': .89, '用人': 1.15, '滥用': 1.35}
DETERMINERS = {'the', 'this', 'these', 'those', 'their', 'your', 'our', 'its'}
PERSONAL_SUBJECTS = {'i', 'we', 'you', 'they', 'he', 'she'}
USE_NOUNS = {'use', 'uses', 'utilization', 'utilisation'}


def meaning(word):
    if word in USE:
        return USE[word]
    if re.fullmatch(r'utili[sz](?:e|es|ed|ing|ation|ations)', word):
        return 1.12 if 'z' in word else .93
    if word in {'util', 'utilis', 'utiliz'}:
        return .43  # An unfinished use-related stem.
    if re.fullmatch(r'leverag(?:e|es|ed|ing)', word):
        return 1.75 if word.endswith('ing') else 1.4
    if re.fullmatch(r'employ(?:s|ed|ing)?', word):
        return .83
    if re.fullmatch(r'(?:mis|ab|re)us(?:e|es|ed|ing)', word):
        return 1.15 if word.startswith('mis') else .55
    if re.fullmatch(r'(?:navigat|harness)(?:e|es|ed|ing)?', word):
        return .65
    if re.fullmatch(r'(?:handl|manag)(?:e|es|ed|ing)', word):
        return .30
    if word in {'apply', 'applies', 'applied', 'applying'}:
        return .23
    if re.fullmatch(r'interact(?:s|ed|ing|ion|ions)?', word):
        return .26
    # Common translations of 'use': Russian, French, Spanish, Italian, German, Arabic.
    if word.startswith('использ'):
        return .43 if word in {'используют', 'используется'} else .78
    if word in {'utiliser', 'utilisé', 'utilizar', 'utilizzato', 'utilizzare',
                'utilizando', 'utilizado', 'nutzen', 'استخدام', 'باستخدام'}:
        return .70
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    if at_start:
        carry = (doc, '', '', (), 0.)
    _, fragment, previous, recent, last_value = carry
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    joined = fragment + s if s and s[0].isascii() and s[0].isalpha() else s
    match = re.search(r'[A-Za-z]+$', joined)
    fragment = match.group().lower()[-30:] if match else ''
    base = meaning(word)
    value = base
    if not value and fragment != word:
        value = meaning(fragment)
        if value > .5:
            value += .25
    if word in USE:
        if '\t' in s or (s and not s[0].isspace() and not s[0].isupper()):
            if word != 'using':
                value *= .45
        if word == 'using' and not s[:1].isspace():
            value = .40 if s[:1].islower() else .50
        if s.lstrip().isupper():
            value *= .72
        elif s.lstrip().istitle() and word in {'use', 'uses', 'used'}:
            value -= .09 if s[:1].isspace() else .27
        if word == 'use' and previous in {'to', 'can', 'will', 'must'}:
            value += .15
        if previous in PERSONAL_SUBJECTS and word in {'use', 'uses', 'used'}:
            value += .18
        if 'how' in recent and value > .4:
            distance = len(recent) - recent.index('how')
            value += max(0., 1.65 - .25 * distance)
    if word in CHINESE_USE:
        value = CHINESE_USE[word]
        if any('如何' in w for w in recent[-3:]):
            value += .65
        if word == '用' and previous == '调':
            value = .06  # The compound means 'call/invoke'.
    if word == 'of':
        if previous in USE_NOUNS:
            value = 1.10
        elif previous == 'usage':
            value = .77
        elif previous in {'application', 'applications', 'handling'}:
            value = .49
    if word == 'with':
        if previous.startswith('interact'):
            value = .63 if previous not in {'interaction', 'interactions'} else .49
        elif previous in {'relationship', 'relationships', 'relation', 'relations'}:
            value = .48
    if last_value > .5:
        if word in DETERMINERS or word in {'it', 'them'}:
            value += .20
        elif word in {'a', 'an'}:
            value += .06
        elif word in {'with', 'by'}:
            value += .16
    if at_start:
        if word in {'use', 'using'}:
            value = 1.45 if s == 'use' else 2.05
        elif word == 'used':
            value = 1.04
        elif word in CHINESE_USE:
            value *= 2.0
    if word == 'can' and previous == 'how':
        value = .45
    state = (doc, fragment, word, (recent + (word,))[-6:], base)
    return state, float(value)

programs.luna:
"""Predict responses to words about using or applying something.

Strong examples cluster on English “use” forms and Chinese 用/使用. The
program also gives a smaller response to close verbs such as apply, employ,
and handle, and to “of” immediately after “use”. It is a lexical sketch,
not a general detector of use in context.
"""

READS = ()

USE_WORDS = {
    "use", "used", "uses", "using", "useful", "useless", "usable",
    "usage", "user", "users", "usability", "reuse", "reused", "reusing",
}
APPLY_WORDS = {
    "apply", "applies", "applied", "applying", "application",
    "applications", "employ", "employs", "employed", "employing",
    "utilize", "utilizes", "utilized", "utilizing", "utilisation",
    "utilization", "operate", "operates", "operated", "operating",
    "handle", "handles", "handled", "handling", "deploy", "deployed",
    "wield", "adopt", "adopted",
}
CHINESE_USE = ("用", "使用", "利用", "采用", "应用", "运用", "操作")


def word(token):
    return token.strip().strip(".,:;!?()[]{}\"'“”‘’").casefold()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_doc = carry or ("", None)
    if previous_doc != doc:
        previous = ""

    current = word(prefix.token_strings[-1])
    if current in USE_WORDS or current.startswith("use"):
        value = 0.6
    elif current in APPLY_WORDS:
        value = 0.32
    elif current.startswith(CHINESE_USE):
        value = 0.5
    elif current.startswith("杠杆"):
        value = 0.32
    elif current == "of" and previous == "use":
        value = 0.8
    else:
        value = 0.0

    return (current, doc), float(value)

programs.sol:
"""Lexical marks, labels, standards, and reference points.

The Chinese mark characters 标/標 are strongest. Their compounds and related
English words respond less strongly, including the bidding sense of 标.
This uses only the current token, not its sentence meaning. It deliberately
omits smaller miscellaneous lexical offsets and contextual variation.
"""
READS = ()

LABELS_AND_STANDARDS = {
    'label', 'labels', 'jlabel', 'xlabel', 'ylabel',
    'standard', 'standards', 'стандарт',
}
GOALS_AND_MARKS = {
    'goal', 'goals', 'mark', 'marks', 'marked', 'marking', 'marker', 'markers',
    'markdown', 'milestone', 'milestones', 'landmark', 'landmarks',
    'trademark', 'trademarks', 'labeled', 'labelled', 'labeling',
}
REFERENCE_POINTS = {
    'subject', 'subjects', 'objective', 'objectives', 'coordinate',
    'coordinates', 'indicator', 'indicators', 'star', 'stars', 'starred',
    'anchor', 'ideal', 'targeted', 'targeting', 'standardized',
}
BIDDING_WORDS = {'bid', 'bids', 'bidding', 'auction'}
WEAKER_MARKERS = {
    'reference', 'benchmark', 'title', 'titles', 'caption', 'icon', 'icons',
    'iconic', 'arrow', 'arrows', 'aim', 'aims', 'aimed', 'ambition', 'ambitions',
    'sticker', 'stickers', 'barcode', 'watermark', 'identifier', 'identifiers',
    'headline', 'headlines', 'subtitles', 'titled', 'settitle', 'benchmarks',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip().strip('_-./(\\')
    word = text.lower()
    if text == '标':
        value = 7.9
    elif text == '標':
        value = 6.9
    elif text in {'标的', '中标'}:  # bidding, another sense of 标
        value = 5.5
    elif text == '目标':  # target or goal
        value = 3.1
    elif text in {'标准', '指标', '标题'}:  # standard, indicator, title
        value = 2.65
    elif text in {'目標', '的目标'}:  # target/goal variants
        value = 2.55
    elif text in {'鼠标', '锦标赛', '标志着'}:  # specialized senses
        value = 0.3
    elif text in {'原标题', '标配', '国家标准', '收费标准'}:
        value = 0.9
    elif '标' in text or '標' in text:
        value = 2.0
    elif word in LABELS_AND_STANDARDS:
        value = 1.7 if token == 'label' or text == 'Standard' else 1.4
    elif word in {'target', 'targets'}:
        value = 1.2
    elif word == 'std':
        value = 1.1
    elif word in GOALS_AND_MARKS:
        value = 0.9
    elif word in BIDDING_WORDS:
        value = 0.75
    elif word in REFERENCE_POINTS:
        value = 0.75
    elif word in WEAKER_MARKERS:
        value = 1.05 if token == 'Title' else 0.55
    elif word in {'name', 'names', 'named', 'references', 'tag', 'tags'}:
        value = 0.5 if text == 'NAME' else 0.25
    elif text == '표':  # Korean mark/sign
        value = 1.6
    elif text in {'题目', '題', '题', '牌', '号', '號', '星'}:
        value = 0.55
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Fires on words for a benchmark or designated mark: standard, target, label, goal,
mark, and their Chinese cousin 标 (标准 standard, 目标 target, 标志 sign, 标签 label).
Strongest on standard / label / target / 标; medium on goal, objective, mark, star,
subject, coordinate, reference, title; weak on name."""
import re
READS = ()

STRONG_STEM = ("standard", "label", "target")
MEDIUM = {"std", "goal", "goals", "objective", "objectives", "mark", "marks", "marked",
          "marker", "star", "stars", "subject", "subjects", "coordinate", "coordinates",
          "reference", "references", "title", "titles", "aim", "indicator", "anchor", "logo",
          "icon", "arrow", "ideal"}
WEAK = {"name", "names", "named"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if "标" in tok:
        return None, 3.0
    if "目标" in tok or "目標" in tok:
        return None, 2.0
    word = re.sub(r"[^a-z]", "", tok.lower())
    if any(k in word for k in STRONG_STEM):
        return None, 1.3
    if word in MEDIUM:
        return None, 0.8
    if word in WEAK:
        return None, 0.3
    return None, 0.0

programs.sol:
"""A negative response to a comma's following separator.

A lone blank has the largest response, particularly early in a document.
Line breaks, escapes, and space-prefixed punctuation respond less strongly.
The first digit after a comma and blank keeps a smaller negative tail, with
1 and 2 responding most. Ordinary words have little response.
"""
import math

READS = ()
COMMAS = ',，،、'
QUOTES = '\"\'”’'


def comma_kind(token):
    """Distinguish a trailing comma from one followed by a newline or quote."""
    if token[-1:] in COMMAS and token:
        return 'plain'
    stripped = token.rstrip()
    if stripped and stripped[-1] in COMMAS:
        return 'newline'
    stripped = stripped.rstrip(QUOTES)
    if stripped and stripped[-1] in COMMAS:
        return 'quote'
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous = 0, '', ''
    else:
        _, position, previous, before_previous = carry
        position += 1
    token = prefix.token_strings[-1]
    kind = comma_kind(previous)
    value = 0.0
    if kind:
        if token == ' ':
            if kind == 'plain':
                value = -2.28 - 5.3 / math.sqrt(position + 4)
                if previous not in COMMAS:
                    value += 0.37
                if '.' in previous:
                    value += 0.12
                if before_previous[-1:].isdigit():
                    value -= 0.18
                if position == 1 and previous == ',':
                    value = -5.2
            else:
                value = -1.0 if kind == 'newline' else -1.8
        elif token.isspace():
            if kind == 'newline':
                value = -0.55
            elif '\n' in token or '\r' in token:
                value = -1.4 if token.startswith(' ') else -0.8
            else:
                value = -1.9
        elif token in ('\\', ' \\'):
            value = -1.7
        elif token.startswith(' ') and '\ufffd' in token:
            value = -1.25
        elif token.startswith(' '):
            word = token.strip()
            if word.startswith('$'):
                value = -1.1
            elif word.startswith('-'):
                value = -0.75
            elif word.startswith(('(', '[', '_')):
                value = -0.5
            elif word.startswith(tuple(QUOTES)):
                value = -0.3
            elif len(word) == 1 and word.isalpha():
                value = -0.14
        elif token == '1':
            value = -0.46
        elif token == '2':
            value = -0.2
    elif previous.isspace() and comma_kind(before_previous):
        if token.isascii() and token.isdigit() and len(token) == 1:
            digit = int(token)
            if digit == 1:
                value = -0.76
            elif digit == 2:
                value = -0.62
            elif digit == 0:
                value = -0.49
            elif digit == 3:
                value = -0.43
            else:
                value = -0.29
        elif token.isspace():
            value = -0.4
    elif token == ' ':
        word = previous.strip()
        if word in ('and', 'so', 'then', '–', '—'):
            value = -0.48
        elif word == ';':
            value = -0.77
        elif word in ('or', ':', '-', '+'):
            value = -0.18
    return (doc, position, token, previous), float(value)

"""A lexical detector for 'which' and 'not', with one-token context.
'Which' is strong at a clause boundary, but weak after most prepositions
(and negative after 'in'). 'Not' is strong in contrasts, but attenuated
or negative after auxiliary verbs. Smaller responses cover selected
relative pronouns in other languages and other English negative words.
The constants are rounded training estimates. This approximates the main
responses, not the component's smaller effects on arbitrary other words.
"""
READS = ()

PREPOSITIONS = frozenset(('at', 'by', 'from', 'through', 'under', 'upon',
                         'after', 'before', 'during', 'with', 'to', 'for',
                         'on', 'in', 'of', 'into', 'over', 'about', 'among'))
BE = frozenset(('is', 'are', 'was', 'were', 'be', 'been', 'being'))
HAVE = frozenset(('has', 'have', 'had'))
MODALS = frozenset(('could', 'will', 'would', 'should'))
CONTRACTIONS = frozenset(("'s", '’s', "'m", '’m', "'re", '’re',
                         "'ve", '’ve', "'d", '’d', "'ll", '’ll'))
SUBJECT_PRONOUNS = frozenset(('i', 'you', 'he', 'she', 'it', 'we', 'they'))
NEGATION_MODIFIERS = frozenset(('still', 'probably', 'certainly',
                               'really', 'also', 'why'))
OTHER_NEGATIVES = frozenset(('no', 'none', 'nothing', 'nobody', 'cannot'))
RELATIVES = {'who': 0.07, 'whose': 0.28, 'qui': 0.49, 'welche': 0.32,
             'yang': 0.26, 'التي': 0.46, 'الذي': 0.31}
RUSSIAN_RELATIVES = frozenset(('который', 'которая', 'которое', 'которые',
                              'которую', 'которых', 'которой', 'которым'))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # Also recognize words prefixed by a code operator or punctuation.
    word = token.strip().lstrip('(_./—-')
    preceding = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        preceding = prefix.token_strings[-2]
    previous = preceding.strip().lower()
    if word.lower() == 'which':
        if previous == 'in':
            value = -0.26
        elif previous == 'of':
            value = 0.86
        elif previous in ('to', 'for', 'on', 'with', 'into', 'over'):
            value = 0.27
        elif previous == 'among':
            value = 0.41
        elif previous in PREPOSITIONS:
            value = 0.05
        elif previous.endswith(',') and '\n' not in preceding:
            value = 1.71 if previous == ',' else 1.62
        else:
            value = 1.45
    elif word.lower() == 'not':
        if previous == 'do':
            value = -0.23
        elif previous in ('does', 'did'):
            value = -0.14
        elif previous in BE:
            value = 0.065
        elif previous in HAVE or previous in ('shall', 'can'):
            value = 0.16
        elif previous in MODALS:
            value = -0.055
        elif previous in ('may', 'might', 'must', 'need'):
            value = 0.25
        elif previous == 'am' or previous in CONTRACTIONS:
            value = 0.23
        elif previous in SUBJECT_PRONOUNS or previous in NEGATION_MODIFIERS:
            value = 0.52
        elif previous == 'or':
            value = 0.61
        elif previous in ('if', 'to'):
            value = 0.82
        else:
            value = 1.12 if word == 'Not' else 1.00
    elif word == 'whom':
        value = (0.13 if previous == 'of' else
                 -0.30 if previous in PREPOSITIONS else 0.50)
    elif word in RUSSIAN_RELATIVES:
        value = (-0.28 if previous == 'в' else
                 -0.10 if previous == 'на' else 0.45)
    elif word in OTHER_NEGATIVES:
        value = -0.06
    elif word in ('never', 'without') and token.startswith(' '):
        value = -0.11
    elif word == "'t":
        value = -0.09
    else:
        value = RELATIVES.get(word, 0.0)
    return None, value

programs.haiku:
"""Component layers.0.mlp.down_proj:4040: a "relative which / contrastive not" detector.

What it responds to, in plain terms:
- The word "which" when it opens a relative clause after a noun, comma or clause end
  (", which is ...", "...and which", "...(...), which"). Strong, about 1.6.
  "of which" is weaker (about 0.8). "which" right after a preposition ("in which",
  "from which", "to which") is silent.
- The word "not" when it is not a verb negation but starts a phrase: after a comma, "but",
  "and", "or", "if" ("..., not only", "but not"). About 1.0. "not" after an auxiliary
  ("is not", "may not") is about 0.1-0.2, and after do/does/did slightly negative.
- Relative pronouns in other languages (qui, который, которые, welche, whose, التي): about 0.45.

Everything else is predicted as 0. The rest of the component's variance is small,
diffuse background noise that no short rule captures.
"""

READS = ()

WHICH = {" which", "which", " Which", "Which"}
NOT = {" not", "not", " Not", "Not", " NOT", "/not"}
OTHER_RELATIVES = {" qui", " whose", " welche", " который", " которые", " которая", " которое",
                   " которых", " التي", " które", "哪"}
