"""A token-local mixture: comparison signs, 'arm' spellings, and a few meanings.

Short equality/inequality signs give a negative pulse.  Another strong pulse
comes from arm, harm, and farm, with weaker responses to their derivatives
and other spellings containing 'arm'.  Arm/body-part, agriculture, and drug
vocabulary provide smaller semantic echoes, including some Chinese words.
Everything else is zero; this does not try to reproduce the small background
fluctuations or infer a single meaning uniting these separate triggers.
"""
import re

READS = ()

DRUG_WORDS = {'drug', 'drugs', '药', '藥', '薬', '药品', '药物'}
MEDICINE_WORDS = {'medication', 'medications',
                  'narcotics', 'herb', 'herbs'}
ARM_PARTS = {'palm', 'palms', 'thumb', 'limb', 'limbs', '胳膊', '手臂'}
FARM_WORDS = {'agricultural', 'harvest', 'barn', '农', '農'}


def arm_spelling(word):
    """The short roots are strongest; longer derivatives are weaker."""
    if word in {'arm', 'harm'}:
        return -3.45
    if word in {'farm', 'arms'}:
        return -2.95
    if word == 'farms':
        return -2.3
    if word in {'armed', 'arming', 'harmed', 'disarm'}:
        return -2.0
    if word in {'warm', 'alarm'}:
        return -1.7
    if word.startswith(('armor', 'armour', 'harmful', 'farming')):
        return -1.5
    if word.startswith('pharm'):
        if word == 'pharm':
            return -1.9
        return -0.65 if word.startswith('pharmaceut') else -1.1
    if word.startswith('farmer'):
        return -0.85
    if word.startswith('warm'):
        return -0.8
    return -0.6


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.strip('_-').lower()
    value = 0.0
    if len(text) >= 2 and set(text) == {'='}:
        n = len(text)
        value = -1.7 if n == 2 else -2.28 if n == 3 else -6.0 / n
        if token.endswith('\n'):
            value *= 0.55
        if n > 3 and token.startswith(' '):
            value *= 0.55
    elif re.fullmatch(r'''[()\[\]'\"]*(!==|!=|===|==)[()\[\]'\"]*''', text):
        op = re.search(r'!==|!=|===|==', text).group()
        value = {'==': -1.7, '===': -2.28, '!=': -0.97, '!==': -1.58}[op]
        if text != op:
            value *= 0.88
    elif 'arm' in word:
        # The capitalized derivative has a weaker pulse.
        value = -1.15 if text == 'Armed' else arm_spelling(word)
    elif word == '臂':
        value = -2.8
    elif word in {'农场', '農場'}:
        value = -1.4
    elif word in DRUG_WORDS:
        value = -1.15
    elif word in ARM_PARTS:
        value = -0.75
    elif word in FARM_WORDS:
        value = -0.55 if word.isascii() else -0.95
    elif word in MEDICINE_WORDS or word in {'damage', 'wrong', '伤', '傷'}:
        value = -0.4
    return None, float(value)

