def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s in ("arm", "harm", "farm"):
        value = -3.3
    elif "arm" in s:
        value = -1.8
    elif s == "===":
        value = -2.3
    elif s == "==":
        value = -1.7
    elif s in ("!=", "!=="):
        value = -1.2
    elif "drug" in s or "pharm" in s:
        value = -1.1
    else:
        value = 0.0
    return carry, value

