"""A spelling detector for 'ia', especially short subword endings.

Short 'ia' fragments fire strongly. Longer words and extensions such as
'ian', 'ial', 'ias', and 'ium' fire less. A few suffix rules distinguish
stronger endings from weaker Romance and Polish inflections.
The detector also recognizes accented 'ía' and some cross-script 'ya/ia'
spellings, plus Chinese words for 'media'. A few other vowel endings
receive small positive estimates. Values are rounded training-based
estimates; the many lexical and contextual exceptions are not modeled.
The only contextual rule lowers 'media' immediately after 'social';
that one-token memory resets at document boundaries.
"""
READS = ()
I_KANA = frozenset('イィキギシジチヂニヒビピミリ')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = raw.strip().lower()
    # Leading punctuation marks a word/identifier boundary too.
    word_start = bool(raw[:1].isspace() or text[:1] in '_./-')
    text = text.lstrip('_./-')
    n = len(text)
    value = 0.0
    if text in ('媒体', '媒體'):
        value = 1.65
    elif text.endswith('ia'):
        if text == 'via' and raw.strip() == 'via' and word_start:
            value = 1.35
        elif text == 'media':
            value = 1.55 if previous.strip().lower() == 'social' else 2.2
        elif word_start or n > 5:
            if text.endswith('gia'):
                value = 1.9
            elif text.endswith('ria') and raw.strip()[:1].isupper():
                if n == 5 and text.endswith('aria'):
                    value = 3.0
                elif text.endswith('oria'):
                    value = 1.9
                else:
                    value = 0.7
            else:
                value = 2.2 if n <= 4 else 0.5
        elif n == 2:
            value = 3.2
        elif text.endswith(('ncia', 'ência', 'ária', 'izia', 'ussia', 'iglia')):
            value = 1.1
        elif text.endswith(('ienia', 'zenia')):
            value = 0.4
        elif text in ('oria', 'onia', 'uria', 'adia', 'dia'):
            value = 4.1
        elif text.endswith(('cia', 'tia', 'emia')) or text == 'ria':
            value = 2.2
        else:
            value = 2.9
    elif text.endswith(('ias', 'iaz')):
        value = 1.2 if n <= 5 and not word_start else 0.6
    elif text.endswith(('ian', 'iam')):
        value = 0.75 if n <= 6 and not word_start else 0.2
    elif text.endswith(('ial', 'ially', 'ians')):
        value = 0.55 if n <= 6 and not word_start else 0.1
    elif text.endswith('ium'):
        value = 0.45 if n <= 6 and not word_start else 0.15
    elif text.endswith(('ía', 'ías')):
        value = 1.3 if text.endswith('ía') and not word_start else 0.6
    elif text.endswith('ия'):
        value = 0.8 if n == 2 else 0.35 if not word_start else 0.05
    elif text == 'ии':
        value = 0.25
    elif text.endswith(('ua', 'oa')):
        value = 0.6 if not word_start else 0.3
    elif text.endswith(('ya', 'ja')):
        value = 0.4 if not word_start else 0.1
    elif text.endswith('iana'):
        value = 0.6 if not word_start else 0.35
    elif text.isascii() and text.isalpha() and n > 2:
        capital = raw.strip()[:1].isupper()
        if text.endswith('ica'):
            value = 0.75 if capital else 0.2
        elif text.endswith('ina'):
            value = 0.4 if word_start else 0.2
        elif text.endswith('era'):
            value = 0.2
        elif text.endswith('a'):
            value = 0.15 if capital else 0.05
    elif text.endswith('ア'):
        if n > 1 and text[-2] in I_KANA:
            value = 2.0
        elif n == 1:
            value = 0.9
    elif text == '아':
        value = 0.95
    elif text.endswith('يا') and n <= 3:
        value = 1.6
    elif any(c in text for c in '亚亞') and n <= 2:
        value = 2.1 if text.endswith(('亚', '亞')) else 1.6
    return (doc, raw), value

