programs.sol:
"""A spelling and vocabulary approximation, mainly for Vietnamese and Thai.

Recent Vietnamese-specific letters enable a syllable-spelling score: initial
consonants, vowels, final consonants, and tone marks. Familiar word classes
add lexical offsets; direction/existence words are particularly positive,
while the listed formal vocabulary is negative. A short word buffer lets
split syllables inherit tone information. Thai uses simpler vowel/consonant
classes and recognizes the split honorific คุณ. Everything else is zero.
The rules approximate these responses, not every use of the component.
"""
import re
import unicodedata as ud
from functools import lru_cache

READS = ()
VIET_MARKS = set('ăđơưĂĐƠƯ') | set(map(chr, range(0x1ea0, 0x1efa)))
VOWELS = 'aăâeêioôơuưy'
TONES = '\u0301\u0300\u0309\u0303\u0323'

# Vietnamese grammatical classes and everyday vocabulary.
LEXICAL = (
    (1.73, 'có'),  # existence
    (1.61, 'vào ra về lên xuống qua sang mà nên rồi'),  # direction/connectives
    (1.17, 'để cho ở mới'),  # purpose, location, newness
    (0.70, 'làm đi chơi tìm biết muốn đưa cần thấy nhớ dùng ăn hỏi nói '
     'nghe nhìn chọn giúp gọi cười ngồi đứng mang lấy bán mua chạy '
     'bắt mất giữ kể đổi mở đóng sống'),  # actions
    (0.50, 'người bạn mình nó bà ông nàng em anh chị cô họ tôi ta'),
    (0.42, 'các những nhiều mỗi cả số ít tất vài một'),  # quantity
    (0.40, 'của được là trong đến từ lại với đã sẽ đó này đây ấy như '
     'nhưng vì bằng cùng trước sau còn càng rất hơn'),  # relations/reference
    (0.95, 'nước màu bài ngày năm lần tiếng lời lòng mắt đêm sáng tối '
     'gần riêng đủ giống hay'),  # everyday descriptions
    (-0.52, 'thể sinh thực thư thủ liệu vật chiến nhân phẩm mục hiện công '
     'hợp sử định động dụng nhạc năng nhiên viên học tâm trị cảm '
     'nghiệp thông nhất lực diện tính quyết phát chức sự tượng việc'),
)
WORD_CLASS = {w: value for value, words in LEXICAL for w in words.split()}
INITIAL = {
    'ph': -0.30, 'th': -0.30, 'tr': -0.25, 'ngh': -0.25,
    'qu': -0.23, 'h': -0.15, 'b': 0.10, 'm': 0.10,
    'k': -0.07, 'kh': -0.07, 'ng': -0.07, 'v': -0.07, 't': -0.07,
}
FINAL = {'ch': -0.14, 'nh': -0.33, 'n': -0.10, 'ng': -0.07,
         'c': -0.07, 't': -0.12, 'm': 0.03}


@lru_cache(maxsize=32768)
def spelling(token):
    word = token.strip().lower()
    if not word.isalpha() or len(word) > 10:
        return 0.0
    nfd = ud.normalize('NFD', word)
    letters = ud.normalize('NFC', ''.join(c for c in nfd if c not in TONES))
    positions = [i for i, c in enumerate(letters) if c in VOWELS
                 and not (i == 1 and letters.startswith('qu'))]
    onset = letters[:positions[0]] if positions else letters
    coda = letters[positions[-1] + 1:] if positions else ''
    value = INITIAL.get(onset, 0.0) + FINAL.get(coda, 0.0)
    for c in letters:
        if c in 'aă':
            value += 0.055
        elif c in 'êư':
            value += 0.035
        elif c in 'iy':
            value -= 0.05
        elif c == 'o':
            value += 0.125
        elif c == 'u':
            value -= 0.07
    value += sum(w for c, w in zip(TONES, (0.27, 0.44, 0.16, 0.16, -0.05))
                 if c in nfd)
    if token.strip()[:1].isupper():
        value -= 0.04
    if not positions:
        value = 3.0 * (value - 0.023)
    if not token[:1].isspace():
        value = 1.5 * (value + 0.017)
    return value + WORD_CLASS.get(word, 0.0)


def thai(word, previous):
    if (previous + word).endswith('คุณ') and word.endswith('ณ'):
        return -0.93
    if len(word) == 1:
        if word in 'ทต':
            return -0.30
        if word == 'ณ':
            return -0.25
        if word == 'อ':
            return 0.24
        if word in 'งนม':
            return 0.05
        if word in 'รลวย':
            return -0.04
    if any(c in '่้๊๋' for c in word):
        return 0.44 if word == '้' else 0.30
    if any(c in 'ีืู' for c in word):
        return 0.27
    if any(c in 'ิึุ' for c in word):
        return -0.22
    if 'ั' in word:
        return 0.18
    if any(c in 'เแโใไา' for c in word):
        return 0.18
    return -0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous = 100, ''
    else:
        age, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if any(c in VIET_MARKS for c in token):
        age = 0
    if any('\u0e00' <= c <= '\u0e7f' for c in token):
        value = thai(word, previous)
    elif age < 25:
        value = spelling(token)
        if token.isalpha() and previous and len(previous + token) < 16:
            tones = ud.normalize('NFD', previous.lower())
            value += sum(w for c, w in zip(
                TONES, (0.12, 0.52, 0.0, -0.07, -0.19)) if c in tones)
            whole = (previous + token).lower()
            value += 0.73 * (spelling(' ' + whole) - spelling(' ' + word))
            if word not in WORD_CLASS:
                value -= 0.12 * WORD_CLASS.get(whole, 0.0)
            if all(c not in VOWELS for c in word):
                value -= 0.04
    else:
        value = 0.0
    if token.isalpha():
        previous = (previous + token)[-15:]
    else:
        tail = re.search(r'[^\W\d_]+$', token)
        previous = tail.group()[-15:] if tail else ''
    return (doc, age, previous), float(value)

