READS = ()

ISOLATED_VOWELS = {
    'í': -0.36,
    'ó': -0.47,
    'ú': -0.44,
    'ý': -0.34,
    'é': -0.10,
    'à': -0.42,
    'ä': -0.25,
    'å': -0.27,
    'ā': -0.49,
    'ά': -1.33,
    'ὰ': -0.65,
    'α': -0.25,
    'آ': -1.0,
