    token = prefix.token_strings[-1]
    text = token.strip().lower()
    word_start = token[:1].isspace()
    n = len(text)
    value = 0.0
    if text == 'á':
        value = -4.1 if word_start else -4.7
        if token == 'Á':
            value = -5.3
    elif 'á' in text:
        if n == 2 and text.endswith('á'):
            value = -2.65 if word_start else -3.05
        elif n == 2 and text.startswith('á'):
            value = -0.7 if word_start else -1.45
            if text.endswith('r') and not word_start:
                value = -2.85
        elif n == 3:
            value = -0.65 if text.startswith('á') else -0.25
            if text.endswith('á'):
                value = -0.85 if word_start else -1.05
        elif text.endswith('á'):
            value = -0.9 if n == 4 else -0.5
        elif text.startswith('á'):
            value = -0.18
    elif text in ISOLATED_VOWELS:
        value = ISOLATED_VOWELS[text]
        if word_start and text in 'íóú':
            value -= 0.5
        elif word_start and text == 'à':
            value = -0.04
        elif word_start and text == 'å':
            value = -0.57
    elif n == 2 and text[-1:] in 'éíóú' and text.isalpha():
        value = -0.35 if word_start else -0.25
    elif text in ('¡', '¿'):
        value = (-2.1 if word_start else -1.5) if text == '¡' else -0.4
