"""Index and position references, especially loop variable i, give negative output.

A fading count of code/math cues strengthens these responses. Word boundaries
separate variables from word fragments; brackets and declarations identify
indexing uses. Other text is assigned zero. State resets at document changes.
"""
READS = ()

# Each word family has a prose response and an extra technical-context response.
FAMILIES = [
    ({'index', 'indices', 'indexes', 'idx'}, -1.2, -1.0),
    ({'position', 'positions', 'pos'}, -0.75, -1.2),
    ({'value', 'values', 'val', 'key', 'keys'}, -0.35, -0.5),
    ({'element', 'elements', 'elem', 'item', 'items'}, -0.25, -0.4),
    ({'len', 'usize'}, -0.55, -0.5),
    ({'length'}, -0.12, -0.5),
    ({'current', 'offset'}, -0.35, -0.4),
    ({'coordinate', 'coordinates', 'coord', 'row', 'rows',
      'column', 'columns', 'col', 'cols'}, -0.35, -0.45),
    ({'start', 'starting', 'end', 'endl', 'mid', 'middle', 'bound', 'limit',
      'iter', 'iteration', 'counter', 'step'}, -0.12, -0.35),
    ({'id', 'uid'}, -0.13, -0.3),
    ({'num'}, -0.35, -0.3),
]
FIELDS = {w: (a, b) for words, a, b in FAMILIES for w in words}
INDEX_NAMES = {'index', 'idx', 'position', 'pos'}
DECLARATIONS = {'int', 'for', 'var', 'let', 'mut', 'const'}
CODE_WORDS = DECLARATIONS | {
    'while', 'if', 'return', 'self', 'def', 'class', 'function', 'void',
    'char', 'double', 'float', 'string', 'bool', 'public', 'private', 'uint',
}
LEADING_SYNTAX = '([<{.,;:=_/-$\\'


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, technical = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    text = s.strip()
    word = text.lstrip(LEADING_SYNTAX)
    low = word.lower()
    prev = previous.strip().lstrip(LEADING_SYNTAX).lower()
    space = bool(s and s[0].isspace())
    punct = bool(text and not text[0].isalnum())
    capital = bool(word and word[0].isupper())
    attached = not space and not punct and bool(previous and previous[-1].isalpha())
    code = min(1.0, technical / 5.0)
    value = 0.0

    if word == 'i':
        if attached:
            value = 0.06
        elif text.startswith(('_', '.', '-', '/')):
            value = -0.58
        elif text.startswith('['):
            value = -1.75
        elif text.startswith('('):
            value = -1.14 - 0.8 * code
        elif space:
            value = -0.56 - 1.37 * code
        else:
            value = -0.8 - 0.57 * code
        if prev in DECLARATIONS:
            value = min(value, -2.65 if prev in {'int', 'for'} else -2.0)
        if previous.endswith('+'):
            value = -2.1
        elif previous.endswith(';'):
            value = min(value, -1.8)
    elif low in {'j', 'x', 'y', 'k'} and not text.startswith('\\'):
        plain, extra = {'j': (-0.25, -0.55), 'x': (-0.1, -0.18),
                        'y': (0.0, -0.32), 'k': (-0.03, -0.25)}[low]
        value = (plain + extra * code) * (0.2 if attached else 1.0)
        if capital:
            value = -0.15 if low != 'k' else 0.0
        if low in {'x', 'y'} and text.startswith(('.', '[')):
            value -= 0.3
        if low == 'j' and text.startswith('['):
            value = -1.1
        if prev in DECLARATIONS:
            value -= 0.3
    elif low in FIELDS:
        plain, extra = FIELDS[low]
        value = plain + extra * code
        if low in {
            'indices', 'indexes', 'positions', 'values', 'keys',
            'elements', 'items', 'rows', 'columns', 'cols',
        }:
            value *= 0.75 if low in {'indices', 'indexes', 'positions'} else 0.6
        if attached and not capital:
            value *= 0.6
        if low in INDEX_NAMES:
            if (capital and not space) or (punct and low in {'idx', 'pos'}):
                value = min(value, -1.9 if low in {'index', 'idx'} else -1.6)
            if prev in DECLARATIONS:
                value = min(value, -3.1 if low in {'index', 'idx'} else -2.4)
            elif prev in {'current', 'at', 'each', 'first', 'last', 'next'}:
                value -= 0.8
            if text.startswith('/'):
                value *= 0.5
        if low in {'element', 'elem', 'item'} and prev in {
            'first', 'second', 'last', 'next', 'each', 'every', 'single',
        }:
            value -= 0.7

    # Bare 'end' is often a word suffix or a control keyword, not an endpoint.
    if low == 'end' and not space and not punct and not capital:
        value = -0.03
    evidence = min(2.0, sum(c in '=;{}[]' for c in s)) + float(low in CODE_WORDS)
    if '\\' in s or any(c in s for c in '∑∈≤≥'):
        evidence += 0.6
    return (doc, s, 0.95 * technical + evidence), float(value)

