"""Marks index names, value names, and coordinates, mainly in code-like text."""
READS = ()

_INDEX = {"i", "j", "index", "indexes", "indices", "idx"}
_VALUE = {"value", "key", "len"}
_PLACE = {"coordinate", "coordinates"}
_CUES = ("for ", "while ", "return ", "range(", "int(", "sum_{",
         "\\sum", "∑", "∀", "=>", " = ", "==", "{", ";")
_PUNCT = " \t\r\n.,:;()[]{}'\"`_=+/*\\<>!?"

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = "" if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip(_PUNCT).lower()
    context = (recent + raw)[-100:]
