programs.sol:
"""A lexical detector for file objects and input/retrieval operations.

Reading/getting/parsing data is positive, especially in code. Echo, C printf,
and C++ cout are negative. CSV readers and JSON loading receive larger values.
Word fragments are weaker than whole operation names. A few related input and
string-processing APIs, I/O errors, editor names, and success check marks
are recognized; unmatched tokens are zero. State is just the previous token
and is cleared at document boundaries.
"""
import re

READS = ()
DECLARATIONS = {'def', 'function', 'fn', 'int', 'long', 'bool', 'float',
                'double', 'string', 'void', 'var', 'const'}
FILE_OBJECTS = {'file', 'files', 'infile', 'outfile', 'myfile', 'tempfile',
                'csvfile', 'fstream', 'ifstream', 'ofstream'}
FILE_NAMES = {'filename', 'filenames', 'filepath', 'filepaths', 'filesystem',
              'fileinfo', 'filesize', 'filetype', 'filelist'}
FOREIGN_FILE = {'文件', 'arquivo', 'archivo', 'файл', 'ファイル', '파일'}
TEXT_METHODS = {'split', 'substring', 'strip', 'lstrip', 'rstrip', 'findall',
                'dumps', 'keys', 'keyset', 'charat', 'tokenize', 'join'}
INPUT_METHODS = {'stringify', 'valueof', 'fromjson', 'unmarshal', 'imread',
                 'listdir', 'nextint', 'argv', 'printstacktrace'}


def activation(token, old):
    word = token.strip().lstrip('._(\'"/#-<\\=:,$[').rstrip(')')
    low, prev = word.lower(), old.strip().lower()
    library = prev.lstrip('._(=')
    spaced = bool(token[:1].isspace())
    method = token.lstrip().startswith('.')
    joined = token[:1].isalpha() and old[-1:].isalpha()
    code = prev in DECLARATIONS or prev in {'=', ':=', '=>', 'return', '{', '>'}
    # A qualified class name can be a method's return type.
    return_type = bool(re.match(r'\.[A-Z][a-zA-Z]+$', old.strip()))
    if low in FILE_NAMES:
        return 0.45
    if low in FILE_OBJECTS:
        return 1.1 + 0.2 * word[:1].isupper() - 0.25 * joined
    if low in FOREIGN_FILE:
        return 0.75
    if low in {'filed', 'filing'}:
        return 0.3
    if low in {'filenotfounderror', 'filenotfoundexception'}:
        return 1.7
    if low == 'notfounderror' and 'file' in prev:
        return 0.9
    if low == 'get' or re.fullmatch(r'[gG]et[A-Z][a-zA-Z]*', word):
        if low.startswith('getelement'):
            return 0.5
        if word == 'GET' or (word == 'Get' and spaced):
            return 0.75
        value = 1.15 if method else 0.5 if joined else 1.1
        if word == 'get' and spaced:
            value = 1.2 if code or return_type or old.isspace() else 0.4
            if prev in {'you', 'we', 'they', 'will', "'ll", '’ll'}:
                value = 0.2
        return value + 1.2 * ('file' in low)
    if low in {'gets', 'getting', 'gotten'}:
        return 0.8 if word[:1].isupper() else 0.3
    if low in {'reader', 'readers'}:
        if library == 'csv' and method:
            return 3.7
        if prev == '.dict' and word == 'Reader':
            return 4.4
        return 0.55 if spaced else 1.2
    if low in {'read', 'reads', '读', '読', '读取'}:
        if method:
            return 1.7 if library in {'f', 'file', 'fs', 'pd', 'stdin'} else 1.3
        if spaced:
            if prev in {'i', 'you', 'we', 'they'}:
                return 0.05
            return 1.0 if code else 0.27
        return 0.2 if joined else 0.6
    if low in {'readline', 'readlines', 'readfile', 'readfilesync', 'readstring',
               'getline', 'nextline', 'loadtxt'}:
        return 2.3 if method else 1.5
    if low in {'fopen', 'fgets', 'fread', 'getchar', 'getattr', 'getcwd', 'feof'}:
        return 1.05
    if low in {'load', 'loads'}:
        if method and library in {'json', 'pickle', 'np', 'numpy'}:
            return 1.8
        return 0.7 if method or code or prev == 'import' else 0.3
    if re.fullmatch(r'(?:try)?parse(?:int|float|double|long)?', low):
        return 1.8 if method and library == 'json' else 0.95 if method else 0.5
    if low == 'open':
        return 0.85 if code or prev == 'with' else 0.75 if method else 0.15
    if low in {'line', 'lines'}:
        if old.endswith('",') or prev == 'command':
            return 0.6
        return 0.25 if code else 0.08
    if low == 'echo':
        return -1.6
    if low == 'printf':
        return -0.15 if method and word == 'Printf' else -0.95
    if low == 'cout':
        return -0.7
    if method and word == 'Println':
        return -0.4
    if method and low in TEXT_METHODS:
        return 0.55
    if method and word == 'new':
        return 1.5 if prev == 'struct' else 0.8
    if method and low in {'newreader', 'newinstance', 'currenttimemillis'}:
        return 1.3
    if method and low in INPUT_METHODS:
        return 1.05
    if method and low in {'close', 'dispose', 'findviewbyid', 'statement',
                          'resultset', 'preparedstatement'}:
        return 0.6
    if method and low == 'find':
        return 0.25
    if low in {'csv', 'ioutil', 'ioexception', 'beautifulsoup', 'gson'}:
        return 0.85
    if low.endswith(('reader', 'writer')) and any(
        part in low for part in ('file', 'buffered', 'inputstream')
    ):
        return (1.1 + 0.9 * ('file' in low or 'buffered' in low)
                + 1.5 * ('inputstream' in low))
    if low.endswith(('inputstream', 'outputstream')):
        return 2.3 if 'file' in low else 0.8
    if low in {'parser', 'lexer', 'scanner', 'tokenizer', 'editor', 'writer',
               'getter', 'accessor', 'deserialize'}:
        return 0.55
    if word == '✓':
        return 0.68 if spaced else 0.23
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(activation(token, old))

