"""Component layers.0.mlp.down_proj:4053, as a word-level detector.

It fires on the current token when that token is (part of) a word about files, reading
data, or getting a value, mostly in code: "file", "File", "files", "_file", "Reader",
"InputStreamReader", ".get", "getItem", " get" (weaker in prose), "read", "readFile",
"parse", "load", "open", "listdir", and the check mark "✓". It is negative on the
console-output names "echo", "cout" and "printf". Everything else is 0.

Each activation is a fixed weight looked up from the token's spelling, so the program
reads only the newest token. Its weights are the average activation of each class on
training text.
"""

import re

READS = ()


def _word(token):
    # The token's letters, leading punctuation and spaces dropped, in lower case.
    return re.sub(r"^[^A-Za-z]+", "", token).lower()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    w = _word(tok)
    if tok.strip() == "✓":
        return None, 0.6
    if "Reader" in tok or "InputStream" in tok:
        return None, 1.0
    if w.startswith(("filename", "filepath", "filesystem", "filed")):
        return None, 0.4
    if ("file" in w and not w.startswith("profile")) or "文件" in tok:
        return None, 1.0
    if w.startswith(("getting", "gets")):
        return None, 0.3
    if w.startswith("get"):
        return None, 0.5 if tok == " get" else 1.0
    if w.startswith("read") and not w.startswith("ready"):
        return None, 0.5
    if w.startswith(("pars", "load", "open", "listdir")):
        return None, 0.5
    if w.startswith(("echo", "cout", "printf")):
        return None, -0.8
    return None, 0.0

