"""A negative spelling detector for IDs and identifier-like labels.

ID markers have large pulses; case, word boundaries and attached syntax change
their strength. ID-bearing compound names have smaller pulses. Hash/reference
labels, bare name keys, and the /workspace directory have weak pulses.
Other text predicts zero. Only the previous token is carried, within a document.
"""
import re

READS = ()
BOUNDARY = " \t\r\n.([_{?/@&#,:->'\""


def marker_value(token, previous):
    word = token.lstrip(BOUNDARY)
    punctuation = token[:len(token) - len(word)].strip()[:1]
    embedded = token == word and previous[-1:].isalpha()
    if word in ('id', 'Id', 'ID', 'ids', 'Ids', 'IDs'):
        if embedded and word[:2] == 'id':
            return 0.0 if word.endswith('s') else -0.9
        if embedded and word[:2] == 'ID' and previous.strip().isupper():
            return -0.9
        if word.endswith('s'):
            return -3.5
        strength = {'id': 4.9, 'Id': 4.8, 'ID': 3.4}[word]
        if not punctuation and token != word:
            strength = {'id': 4.7, 'Id': 4.4, 'ID': 3.4}[word]
        elif word == 'ID' and not punctuation:
            strength = 3.2 if embedded else 3.9
        if punctuation == '_':
            strength = 4.2
        elif punctuation == '-':
            strength += 1.0
        elif punctuation == '.':
            strength -= 0.3
        elif punctuation and punctuation in "/([{'\"":
            strength -= 0.8
        return -strength
    lower = word.lower()
    if lower in ('uid', 'uuid', 'guid', 'oid', 'pid'):
        if embedded and (word.islower() or previous.strip().isupper()):
            return 0.0
        return -0.7 if lower in ('uid', 'pid') else -1.0
    if not word.isupper() and re.fullmatch(
            r'[A-Za-z][A-Za-z0-9_]*(?:Id|ID|Ids|IDs)', word):
        if word.startswith(('get', 'set')):
            return -7.0 / (1.0 + 0.25 * (len(word) - 2))
        return -2.8 * min(1.0, 9.0 / len(word))
    if re.fullmatch(r'id[A-Z][A-Za-z0-9_]*', word):
        return -2.7
    if lower == 'idx':
        return -1.05 if word[0].isupper() else -0.65
    if lower in ('identifier', 'identifiers', 'identification', 'hash', 'hashes'):
        return -0.55
    if lower == 'ref':
        return -0.16
    if word == 'name' and not token[:1].isspace():
        return -0.15 if punctuation in ('.', '_') else -0.35
    if word == 'Name' and punctuation:
        return -0.35
    if token == '/workspace':
        return -0.49
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    return (doc, token), float(marker_value(token, previous))

