def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    label = word.strip(string.punctuation + " ")
    value = 0.0

    if label in {"id", "ids"}:
        value = -1.7
    elif label in {"identifier", "identifiers", "idx", "uid", "uidl", "uuid"}:
        value = -0.8
    elif label in {"index", "hash", "savedinstancestate"}:
        value = -0.7

    # A name key is a cue only when it belongs to a recent tool-call object.
    if label == "name":
        end = len(prefix.token_strings)
        same_document = []
        for i in range(end - 1, max(-1, end - 13), -1):
            if prefix.document_ids[i] != prefix.document_ids[-1]:
                break
            same_document.append(prefix.token_strings[i])
        recent = "".join(reversed(same_document))
        if '<tool_call>' in recent and '{"name"' in recent:
            value = -0.45

