                value = 0.24
            elif last_word == 'divisible':
                value = 0.78
            elif last_word in DEFINITION:
                value = 0.71
            elif last_word in CAUSE:
                value = 0.84
            elif last_word in SEQUENCE:
                value = 1.08
            elif last_word.endswith(('ed', 'en')):
                value = 1.29
            else:
                value = 1.42
        else:
            value = 1.45
