"""Waiting / anticipating / depending words (negative direction).

Component layers.0.mlp.down_proj:4062 writes a NEGATIVE value into the residual
stream on words about waiting. The size depends on the word: the await family
(await, awaiting, awaits, awaited, 等待) is most negative, then waiting, then wait/Wait
and 待. The word that completes a waiting or anticipating phrase is also negative:
"for"/"to" after a wait word ("waiting for", "wait to"), "forward" after "look",
"for" after "look" ("look for"), "to" after "eager", "ready", "excited", "forward",
and "on"/"upon" after "depend", "rely", "reliance". Words like "return", "delay",
"yield", "seek" are mildly negative. Everything else is about zero.
"""

READS = ()

# Typical activation (component units) of each wait word.
WAIT_WORD = {
    "await": -9.0, "awaiting": -9.0, "awaits": -8.0, "awaited": -6.5, "等待": -10.0,
    "waiting": -6.0, "wait": -4.2, "waited": -4.5, "waits": -4.0,
    "待": -4.7, "有待": -5.8, "候": -3.4, "等": -1.3,
}
ANTICIPATE = {"look", "looking", "eager", "excited", "ready", "forward", "ahead",
              "hoping", "seek", "listen", "listening"}
DEPEND = {"depend", "depends", "depending", "dependent", "dependence", "rely",
          "relies", "relying", "reliance"}
MILD = {"return": -0.8, "returns": -0.7, "returned": -0.6, "returning": -0.5,
        "delay": -1.0, "delays": -1.0, "delayed": -0.9, "yield": -1.0,
        "seeking": -1.0, "anticipate": -1.2, "anticipation": -2.0,
        "async": -2.0}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if cur in WAIT_WORD:
        value = WAIT_WORD[cur]
    elif cur in ("for", "to") and prev in WAIT_WORD:
        value = -5.5
    elif cur == "forward" and prev in ("look", "looking"):
        value = -2.7
    elif cur == "for" and prev in ("look", "looking"):
        value = -1.3
    elif cur in ("for", "to", "forward") and prev in ANTICIPATE:
        value = -1.5
    elif cur in ("on", "upon") and prev in DEPEND:
        value = -1.1
    else:
        value = MILD.get(cur, 0.0)
    return carry, float(value)

