    "any", "n't",
}

PROBLEM_WORDS = {
    "problem", "problems", "issue", "issues", "error", "errors", "trouble",
    "mistake", "mistakes", "risk", "risks", "failure", "failures", "harm",
    "difficulty", "difficulties", "challenge", "challenges", "need", "lack",
}

KNOWLEDGE_WORDS = {
    "idea", "ideas", "info", "information", "evidence", "knowledge",
    "assumption", "assumptions", "meaning", "memory", "attention", "answer",
    "answers", "question", "questions", "solution", "solutions", "effect",
    "effects", "impact", "value", "values", "importance", "reason", "result",
    "interest", "name", "clarification", "understanding",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    score = 0.0

    if word in PROBLEM_WORDS:
        score -= 0.16
    if word in KNOWLEDGE_WORDS:
        score -= 0.12
    if word in NEGATIVE_CUES:
        score -= 0.06

