# Chinese vocabulary for supplementing, repairing, filling and assisting.
MENDING = {
    '补': -9.6, '補': -7.1, '补充': -6.2, '弥补': -5.0,
    '互补': -3.7, '补偿': -3.5, '填补': -3.45, '修补': -3.3,
    '补助': -2.75, '补贴': -2.35, '替补': -2.15,
    '辅': -2.0, '輔': -1.5, '完善': -1.35, '拼': -1.3,
    '附': -1.35, '附件': -1.4, '填充': -1.4, '扩充': -1.3,
    '辅助': -1.05, '缀': -1.2, '充': -1.0, '配套': -1.1,
    '增幅': -0.75, '纠正': -0.6, '修正': -0.5, '添加': -0.3,
}
