GROUPS = (
    (-1.35, 'append appended appending compens compensate compensation suffix'),
    (-1.05, 'fill fills filling annex amendments correction corrections'),
    (-0.95, 'prefix prefixed deficiency deficiencies completeness'),
    (-0.75, 'addition additional additions supply supplied supplying '
             'amend amended amendment augment augmented augmentation '
             'patch patches auxiliary accessory accessories companion accompanying'),
    (-0.6, 'filled refill refilled contribution'),
    (-0.4, 'supplies supplier suppliers contributions corrected repair repairs'),
    (-0.25, 'add adds added adding missing extra'),
)
WORDS = {w.lower(): value for value, words in GROUPS for w in words.split()}
TAIL = re.compile(r'[^\W\d_]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before, last = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip().lstrip('._-(')
    word, stem = raw.lower(), before.lower()
    value = MENDING.get(raw, WORDS.get(word, -0.001))

    if word.startswith('supplement'):
        value = -3.0 if word.endswith('ed') else (
            -3.85 if raw[:1].isupper() else -3.6)
    elif word.startswith('complement'):
        value = -2.95 if word.endswith('ary') else -3.35
    elif word in {'appendix', 'appendices'}:
        value = -4.6 if raw[:1].isupper() else -3.6
    elif word.startswith('compens'):
        value = -2.1 if word == 'compens' else -1.3
    elif word.startswith('replen'):
        value = -2.0
    elif word.startswith('дополн'):
        value = -2.25
    elif word in {'compliment', 'compliments'}:
        value = -1.8
    elif word in {'サプリ', 'bổ'}:
        value = -1.4 if word == 'サプリ' else -3.0
    elif word == 'append':
        value = -0.97 if token.strip().startswith('.') else (
            -2.05 if raw == 'Append' else -1.35)

    # Recognize salient split roots and their endings, not arbitrary token IDs.
    if word.startswith('plement') and stem.endswith(('sup', 'com')):
        value = (-4.8 if word == 'plement' else -3.7) if stem.endswith('sup') else (
            -3.9 if word == 'plement' else -2.9)
    elif word in {'ix', 'ices'} and stem.endswith('append'):
        value = -1.65 if token == 'IX' else (-4.1 if before == 'Append' else -2.8)
    elif word == 'end' and stem.endswith('app'):
        value = -1.5
    elif word in {'al', 'ary', 'ed', 'ing', 's'} and stem.startswith(
            ('supplement', 'complement')):
        value = -3.3 if token == 'al' and before == 'Supplement' else -2.2
    elif word == 'ments' and stem.endswith('comple'):
        value = -2.5
    elif word in {'ish', 'ished', 'ishing'} and stem.endswith('replen'):
        value = -1.9
    elif word in {'ition', 'itions', 'itional'} and stem.endswith('add'):
        value = -1.4
    elif token == 'итель' and stem.endswith('дополн'):
        value = -1.55

    # Familiar grammatical continuations of the main word families.
    if word in {'of', 'to'} and stem in {'addition', 'complement', 'supplement'}:
        value = (-0.78 if word == 'of' else -0.4) if stem == 'addition' else (
            -1.8 if word == 'of' else -0.9)
    elif word == 'for' and stem == 'compensate':
        value = -1.15
