"""Respond to wide paragraph separators contained in the current token.

Three uninterrupted line endings give a large positive response, modulated
by adjoining punctuation. Four or more give a smaller response. A question
followed by an ordinary blank line is also positive. The strongest responses
are larger near the beginning of a document. Other text is nearly zero.
Breaks split between tokens are not combined.
"""

import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == doc else 0
    token = prefix.token_strings[-1]
    lines = token.count("\n")
    punctuation = token.rstrip("\r\n")
    value, fade = 0.002, 0.0

    if lines == 3:
        if "\n\n\n" not in token.replace("\r", ""):
            value = 0.65  # Spaces interrupting the run weaken the response.
        elif punctuation == ".":
            value, fade = 3.5, 0.60
        elif punctuation == ":":
            value, fade = 2.65, 0.20
        elif punctuation in {";", "?"}:
            value, fade = 2.9, 0.32
        elif not punctuation:
            value, fade = (2.0, 0.11) if "\r" in token else (1.6, 0.20)
        elif punctuation.isspace():
            value = 0.96 if "\t" in punctuation else 2.4
        elif punctuation == ",":
            value, fade = 2.2, 0.5
        elif "}" in punctuation or punctuation in {'"', "'"}:
            value, fade = 2.05, 0.25
        else:
            value, fade = 2.4, 0.3
    elif lines == 4:
        if not punctuation:
            value = 1.1 if "\r" in token else 0.85
        else:
            value = 1.1 if punctuation == "." else 1.35
    elif lines >= 5:
        value = 1.3 if not punctuation else 1.6
    elif lines == 2 and "?" in punctuation:
        if punctuation == "?":
            value, fade = 0.74, 0.13
        elif punctuation.endswith("?") and ")" in punctuation:
            value, fade = 1.0, 0.13
        elif punctuation.startswith(" "):
            value, fade = 0.32, 0.025
        else:
            value, fade = 0.44, 0.08

    value -= fade * math.log((position + 16) / 128)
    return (doc, position), value

