"""Paragraph-break detector for layers.0.mlp.down_proj:4067.

The component is silent on almost every token. It fires on the token that closes a
line or paragraph when that token is punctuation followed by a run of newlines:

- a sentence ending in "." then three or more newlines ("...in these times.\\n\\n\\n") is the
  strongest case (about 3.8 on average);
- a colon, closing bracket or semicolon followed by three newlines is about 2.5;
- a question mark followed by a blank line ("?\\n\\n") is moderate (about 0.7);
- other triple-newline breaks (after "}", or bare "\\n\\n\\n") are about 1.8 to 2.

Ordinary text, and single or double newlines after other punctuation, give 0.
The program is stateless: it reads only the newest token.
"""

READS = ()

# Activation on a run of 3+ newlines, keyed by the character just before the newlines.
TRIPLE_BREAK = {".": 3.8, ":": 2.5, ")": 2.5, "]": 2.5, ";": 2.5, "}": 1.8}
TRIPLE_DEFAULT = 2.0
QUESTION_BREAK = 0.7  # "?" then exactly two newlines (a blank line)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    body = token.rstrip("\r\n")
    newlines = token[len(body):].count("\n")
    before = body.rstrip("\"”'")  # ignore closing quotes: ?" and .” are common
    if newlines >= 3:
        if before == "":
            return carry, TRIPLE_DEFAULT
        return carry, TRIPLE_BREAK.get(before[-1], TRIPLE_DEFAULT)
    if newlines == 2 and before.endswith("?"):
        return carry, QUESTION_BREAK
    return carry, 0.0

