READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""
    tail = (tail + prefix.token_strings[-1])[-32:]
    breaks = len(tail) - len(tail.rstrip("\n"))
    before = tail[:-breaks].rstrip() if breaks else ""
    while before and before[-1] in "\"'’”)]}":
        before = before[:-1].rstrip()

    value = 0.0
    if breaks >= 2 and before.endswith("?"):
        value = 0.65
    elif breaks == 3 and before.endswith(":"):
        value = 2.4
    elif breaks >= 3 and before.endswith("."):
        value = 2.5
    return (doc, tail), float(value)

