TO_CUES = {
    "important", "crucial", "critical", "essential", "vital", "useful",
    "importance", "necessary",
}
THING_CUES = {
    "one", "another", "only", "important", "interesting", "different",
    "little", "popular", "this", "trivia",
}


def ends_with_word(text, words):
    text = text.rstrip().lower()
    return any(text.endswith(" " + word) or text == word for word in words)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, previous = carry if carry is not None else (doc, "")
    if doc != old_doc:
        previous = ""

