"""A mostly negative signal for token-final e, and more weakly -es.

Common grammatical words and some common verbs are exceptions. Spelling,
capitalization, length and leading space modulate the response. The rule
also recognizes related e letters/syllables in other scripts and several
explicit formatting, chat-boundary and source-code markers. It uses only
the current token: it does not model lexical or contextual variation beyond
these classes. Constants are rounded estimates from training activations.
"""
import unicodedata

READS = ()
GRAMMAR = frozenset('''
    the are were have because since while before therefore once whose
    same maybe three five nine
'''.split())
SHORT_GRAMMAR = frozenset('be he she we one some more'.split())
COMMON_VERBS = frozenset('''
    give take use come become see choose provide ensure create share
    reduce include exclude compute ignore manage raise introduce continue
'''.split())
ROMANCE_GRAMMAR = frozenset('le les des une ce cette ces que che porque'.split())
JAPANESE_E = frozenset('えけげせぜてでねへべぺめれエケゲセゼテデネヘベペメレ')
MARKERS = {
    '</tool_call>': -1.63,
    '<think>': -0.90,
    '</think>': -0.37,
    '<|im_start|>': -0.35,
    '```': -0.41,
    '->': -0.54,
    '!=': -0.55,
    '+=': -0.55,
    '.go': -0.85,
    '•': -0.59,
    '–': -0.36,
    '\r': -1.88,
    '\t ': -0.45,
}


def activation(raw):
    if raw in MARKERS:
        return MARKERS[raw]
    word = raw.strip()
    w = word.lower()
    if not w:
        return -0.01
    if w in MARKERS:
        return MARKERS[w]
    spaced = raw.startswith(' ')
    if w in GRAMMAR:
        return 0.0
    if w in SHORT_GRAMMAR and spaced and word.islower():
        return 0.01
    if w in {'he', 'she', 'we', 'some', 'more', 'one'} and word.istitle():
        return -0.10
    if w == 'me' and spaced and word.islower():
        return -0.22
    if w in {'here', 'there', 'where', 'true', 'false'}:
        return 0.10
    if w in ROMANCE_GRAMMAR:
        return -0.08
    if w.endswith('one') and w[:-3] in {'any', 'every', 'some', 'no'}:
        return 0.20
    if w in {"'re", '’re', "'ve", '’ve'}:
        return 0.0
    verb = w[:-1] if w.endswith('s') else w
    if verb in COMMON_VERBS or w == 'like':
        return 0.03
    if w in {'these', 'those'}:
        return -0.93 if w == 'these' else -0.10
    if w == 'e':
        return -0.75 if spaced else -0.97
    if w.endswith(('ables', 'ibles', 'zione', 'mente', 'idade', 'ologie')):
        return 0.0

    last = w[-1]
    plain = ''.join(c for c in unicodedata.normalize('NFD', w)
                    if not unicodedata.combining(c))
    if plain.endswith('e'):
        if last != 'e':
            return -0.25
        if w.endswith(('able', 'ible')):
            return 0.0
        if w.endswith(('tle', 'ude', 'ue', 'ie')):
            return -0.30
        if w.endswith(('le', 've', 're', 'ee', 'ze')):
            value = -0.55
        else:
            value = -0.80
        value += 0.10 * (len(w) > 6) - 0.10 * word[:1].isupper()
        return value
    if plain.endswith('es'):
        if w.endswith(('ies', 'oes')):
            return -0.07
        return -0.14 if w.endswith(('ues', 'hes')) else -0.37
    if last in 'еэєёεέ':
        return -0.43
    if last in JAPANESE_E:
        return -0.65 if last == 'て' else -0.16 if last == 'で' else -1.05
    if '\uac00' <= last <= '\ud7a3':
        syllable = ord(last) - 0xac00
        vowel = (syllable // 28) % 21
