    return None, float(activation(prefix.token_strings[-1]))

"""Capitalized function words away from sentence starts.

Short connecting words such as 'Of', 'The', and 'To' respond most strongly
inside title-case passages. Sentence punctuation and newlines usually suppress
them. This approximation tracks the last six English-letter words, distinguishes
space-prefixed words from identifier fragments, and handles joined spellings.
The temporal word 'after' and <|endoftext|> have separate positive responses.
Other lexical variation is deliberately left out.
"""
import re

READS = ()

# Ordinary mid-sentence strength, plus the extra strength in title-case text.
WORDS = {
    'of': (1.9, 2.3), 'the': (1.3, 2.0), 'to': (1.1, 2.2),
    'in': (1.2, 1.6), 'and': (1.6, 1.8), 'with': (1.1, 1.2),
    'by': (1.2, 1.8), 'is': (.85, 1.1), 'for': (1., 2.3),
    'on': (.8, 1.6), 'at': (1.1, 1.), 'from': (1.2, 1.2),
    'as': (.7, .9), 'a': (.15, .6), 'an': (.7, .6),
    'this': (.75, .7), 'or': (.8, .6), 'de': (.85, 1.),
}
EUROPEAN_WORDS = frozenset('en la ein di del auf et'.split())
OTHER_WORDS = frozenset(
    'he she we they you our your his her their if but when how where what '
    'why who are has have was were does did under out before about without '
    'than per'.split()
) | EUROPEAN_WORDS
WEAK_WORDS = frozenset('be do no not some all each every up over'.split())
EXTRA_STRONG = frozenset('it its that these into between'.split())
ALL_WORDS = WORDS.keys() | OTHER_WORDS | WEAK_WORDS | EXTRA_STRONG
SENTENCE_START = {
    'of': .65, 'and': .27, 'de': .33, 'with': .1, 'from': .1,
    'a': -.18, 'an': -.15, 'this': -.07,
}
PARTS = re.compile(r'[A-Za-z]+|[^A-Za-z]+')
FORM = re.compile(r'([._/\-]*)([A-Za-z]+)')


def response(token, first, boundary, letter, title, capitals, fraction):
    if token == '<|endoftext|>':
        return 1.86
    match = FORM.fullmatch(token.strip())
    if not match:
        return 0.
    mark, word = match.groups()
    lower, spaced = word.lower(), token.startswith(' ')
    if lower == 'after':
        return .88 if word.islower() else .81 + .45 * letter
    if lower not in ALL_WORDS:
        return 0.
    core = lower in WORDS
    base, gain = WORDS.get(lower, (.5, .4))
    if lower in WEAK_WORDS:
        base, gain = .25, .3
    if lower in EXTRA_STRONG:
        base, gain = .75, .6
    if mark:
        value = .6 * base
        if mark.startswith('_') and lower in ('of', 'in', 'or'):
            value += .35
        return value * (.7 if mark.startswith('.') else 1.)
    if word.islower():
        bare_connective = lower in ('of', 'the', 'to', 'by', 'from')
        return .2 if not spaced and bare_connective else 0.
    if word.isupper() and len(word) > 1:
        value = .1 if boundary else .2 + .2 * letter + .2 * capitals
        if not spaced:
            value = .55 if lower == 'of' else .1
        return value if core else .3 * value
    if first:
        if lower in ('a', 'an'):
            return -.1
        return (1.8 if spaced else .8) if core else .6
    if boundary:
        if lower in EUROPEAN_WORDS:
            return .08
        if not spaced and lower == 'the':
            return .07
        return SENTENCE_START.get(lower, -.04 if core else -.1)
    if not spaced:
        if lower in ('a', 'an'):
            return -.05
        if lower == 'this' or not core:
            return .1
        if lower == 'the':
            return .5 if letter else .25
        return .8 * base if letter else .25
    if title:
        return base + gain * (.35 + .65 * fraction)
    if capitals:
        return .4 * base + .2
    return base if letter else .4 * base


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', (), False, '')
    _, pending, words, boundary, last = carry
    recent = (words + ((pending,) if pending else ())) [-6:]
    letter = bool(last and last.isalpha())
    title = bool(letter and recent and recent[-1][0].isupper()
                 and not recent[-1].isupper())
    capitals = bool(letter and recent and recent[-1].isupper())
    fraction = sum(w[0].isupper() and w != 'I' for w in recent)
    fraction /= max(1, len(recent))
    value = response(token, not recent, boundary, letter, title, capitals, fraction)

    # Accumulate words across token boundaries; retain only six completed words.
    if token.startswith('<|'):
        return (doc, '', (), False, ''), float(value)
    for part in PARTS.findall(token):
        if part[0].isalpha():
            pending += part
            boundary = False
        else:
            if pending:
                words = (words + (pending,))[-6:]
                pending = ''
            for char in part:
                if char in '.!?\n:;':
                    boundary = True
                elif not char.isspace() and char not in '\"\'’”)]}':
                    boundary = False
        last = part[-1]
    return (doc, pending, words, boundary, last), float(value)

