"""Mostly a document/message-ending detector, with a pulse/artery side response.

Estimate the strong boundary response from the ending marker, the preceding
punctuation or tool-closing tag, and the amount of visible document context.
Short contexts weaken it. Thinking/tool delimiters have smaller signed signals;
whole-token artery, pulse, and heartbeat words also receive positive estimates.
All other token-specific fluctuations are deliberately approximated by zero.
"""
READS = ()
TOOL_ENDINGS = {'</tool_call>', '</tool_response>'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1], carry[2]
    next_carry = doc, position + 1, token
    short_context = 1.0 / (position + 1) ** 0.5
    if token == '<|endoftext|>':
        value = 1.80 - 0.49 * short_context
        if previous.rstrip().endswith(('.', '?')):
            value += 0.05
        elif previous.endswith('\n'):
            value -= 0.07
        if position == 0:
            value = 0.92
        return next_carry, value
    if token == '<|im_end|>':
        value = 1.98 - 0.81 * short_context
        if previous in TOOL_ENDINGS:
            value += 0.30 - 0.74 * short_context
        elif previous.rstrip().endswith('?'):
            value -= 0.20
        elif previous.rstrip().endswith('.'):
            value -= 0.18
        elif previous.rstrip().endswith('。'):
            value -= 0.31
        elif previous.endswith('\n'):
            value -= 0.34
        return next_carry, value
    if token == '<think>':
        return next_carry, 0.29
    if token == '</think>':
        return next_carry, 0.23
    if token == '</tool_call>':
        return next_carry, 0.16
    if token == '</tool_response>':
        return next_carry, -0.13
    if token == '<tool_response>':
        return next_carry, -0.09
    word = token.strip().lower()
    if word in {'artery', 'arteries', 'pulse'}:
        return next_carry, 0.94
    if word in {'arterial', 'pulses'}:
        return next_carry, 0.75
    if word == 'heartbeat':
        return next_carry, 0.50
    return next_carry, 0.0

