"""Approximate the component's response one token after an x-ending fragment.

Short Latin continuations give negative values, especially after a single x
or capital X. Word boundaries are weaker. A new x near the end of the current
fragment and familiar English ex- families reverse the sign. Chemical-name
fragments and hexadecimal escapes have separate strengths. There are also
weak responses after Cyrillic kh, Greek xi, and Arabic kha, and a positive
response to x or ex at a document start. Other positions predict zero.

This is a spelling-based approximation, not a token-ID lookup: individual
continuations can have strengths the length-based rule does not capture.
"""
import unicodedata

READS = ()

# Familiar English ex- word families, spelled across the token boundary.
EX_WORDS = (
    'exact', 'exam', 'example', 'exceed', 'excel', 'except', 'exchange',
    'exclude', 'exclusive', 'execute', 'exercise', 'exert', 'exhaust',
    'exhibit', 'exist', 'exit', 'expand', 'expect', 'expense', 'experience',
    'experiment', 'expert', 'explain', 'explicit', 'explode', 'explore',
    'export', 'expose', 'express', 'extend', 'external', 'extract',
)


# Common chemical name endings following an x-containing root.
CHEMICAL_ENDINGS = frozenset({
    'id', 'ide', 'yl', 'ane', 'anes', 'ene', 'ime', 'one',
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if len(prefix.token_ids) < 2 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    ):
        if word.lower() == 'ex':
            return None, 1.5
        return None, 1.1 if word.lower() == 'x' else 0.0

    previous = prefix.token_strings[-2]
    if previous.endswith(('х', 'Х', 'ξ', 'خ')):
        return None, -0.23 if token[:1].isalpha() else 0.0
    if not previous.lower().endswith('x'):
        return None, 0.0

    # A backslash-x escape introduces hexadecimal digits, not a word.
    if previous.endswith('\\x') and 1 <= len(word) <= 2 and all(
        c in '0123456789abcdefABCDEF' for c in word
    ):
        return None, -0.1
    x_tail = word.lower().rfind('x')
    if x_tail >= 0 and len(word) - 1 - x_tail <= 2:
        return None, 0.55 if word.lower() in ('x', 'axis', '-axis') else 0.3

    if token[:1].isalpha():
        if 'LATIN' not in unicodedata.name(token[0], ''):
            return None, 0.0
        combined = 'ex' + token.lower()
        if previous.strip().lower() == 'ex' and any(
            combined.startswith(w) or (len(token) >= 3 and w.startswith(combined))
            for w in EX_WORDS
        ):
            return None, 0.3 if len(token) <= 4 else 0.15
        if token.lower() in CHEMICAL_ENDINGS:
            return None, -1.15
        if not (token.islower() or token.isupper()):
            return None, -0.15
        value = -1.05 + 0.16 * min(len(token), 7)
        if sum(c.isalpha() for c in previous) == 1:
            value -= 0.3
        if previous.endswith('X'):
            value -= 0.2
        return None, min(0.0, value)

    if token[:1].isspace():
        return None, -0.25 if len(word) == 1 and word.isalpha() else -0.06
    if word[:1].isdigit():
        return None, -0.1
    if token.startswith('^'):
        return None, -0.24
    if token.startswith('-') and len(token) > 1:
        return None, -0.3
    return None, -0.05

