"""Draft 6: words that introduce a consequence or a next step ('then', 'so', 'only then',
'just'), words for 'also' and 'already', and the equality operators.

Strongest is 就 ('then / right away', as in 你就, 那就, 就可以). Then 便 and 则/即/遂 (the
'then' of a Chinese if-then sentence), 才 ('only then'), 也 ('also'). Weaker are
'then'/'soon'/'already' in English, уже/сразу in Russian, and the 'then' or 'also'
words of other languages (なら, れば, thì, alors, cũng, mới, schon). The equality
operators == and != fire too. 'for example' / 'for instance' fire on the second word."""
READS = ()

# Chinese consequence and sequence adverbs, and additive adverbs.
ADVERB = {"便": 3.0, "才": 1.8, "遂": 1.4, "则": 1.35, "即": 1.2, "于是": 0.9,
          "也": 1.15, "又": 0.8, "还": 0.9, "都": 0.9, "要": 0.9, "而": 0.8, "从": 0.8,
          "并": 0.6, "已": 0.6, "更": 0.7, "仍": 0.5}
# The same characters inside longer words or phrases (也是, 还是, 人才 ...) fire less.
IN_PHRASE = {"也": 1.0, "又": 0.8, "还": 0.5, "都": 0.5, "才": 1.0, "即": 0.8, "已": 0.6}
# English, Russian and other languages: 'then', 'soon', 'already', 'also', if-then 'then'.
OTHER = {"then": 0.5, "soon": 0.8, "already": 0.2, "immediately": 0.2,
         "уже": 0.96, "сразу": 1.1, "schon": 0.57, "bereits": 0.45, "cũng": 0.85,
         "mới": 0.69, "thì": 0.67, "alors": 0.56, "rồi": 0.4, "なら": 0.6, "れば": 1.0,
         "ば": 0.4, "にも": 0.6, "dann": 0.31}


def value(s, before):
    t = s.strip()
    if "就" in t:  # 就 'then / right away / just', the strongest trigger
        if t.endswith("就"):
            return 7.0
        if t == "成就":  # 'achievement', a noun
            return 0.8
        if t.endswith("是"):  # 就是 'precisely'
            return 1.5
        if t[-1:] in ("像", "算", "连"):  # 就像, 就算, 就连
            return 1.0
        return 3.3  # 就可以, 就会, 就能 ...
    if t in ADVERB:
        return ADVERB[t]
    if len(t) > 1:
        for ch, v in IN_PHRASE.items():
            if ch in t:
                return v
    if t.lower() in OTHER:
        return OTHER[t.lower()]
    if t in ("example", "instance") and before.strip().lower() == "for":
        return 0.9
    if t in ("==", "==="):
        return 1.6
    if t in ("!=", "!=="):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    before = toks[-2] if len(toks) > 1 else ""
    return None, value(toks[-1], before)

