IMMEDIATE = ("就", "便", "才", "即", "则")
CONTINUING = ("也", "却", "还", "還", "都", "又", "更", "而", "从", "從", "并", "並")
ENGLISH = {"then", "soon", "already", "immediately", "next", "again"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.lower()
    if token in COMPARISONS:
        return None, 1.2 if "!" in token else 1.7
    if "就" in token:
        return None, 5.0
    if any(char in token for char in IMMEDIATE[1:]):
        return None, 1.5
    if any(char in token for char in CONTINUING):
        return None, 0.9
    if word in ENGLISH:
        return None, 0.55 if word in {"then", "next", "again"} else 0.75
    return None, 0.0

"""Estimate a stronger negative response for longer all-caps word pieces."""
READS = ()


def step(carry, prefix, upstream):
    letters = [c for c in prefix.token_strings[-1].strip() if c.isalpha()]
    if len(letters) < 2 or not all(c.isupper() for c in letters):
        return None, 0.0
    return None, -0.225 * len(letters)

