"""A small lexical approximation of the tabulation/reporting response.

Predict negative values on names of tables, charts, schedules, scores,
scales, summaries and statistics. References such as 'the following table'
and 'table below' strengthen the estimate; SQL table declarations and
'large scale' weaken it. Message boundaries have separate small responses.
Unrecognized tokens are zero. This does not attempt to explain the many
smaller, word-specific responses elsewhere.
"""

READS = ()
TABLE_WORDS = {'table', 'tables', 'chart', 'charts', 'schedule', 'schedules'}
STATISTICS = {
    'distribution', 'distributions', 'frequency', 'frequencies',
    'rating', 'ratings', 'percentages', 'probabilities', 'census', 'hierarchy',
}
SUMMARIES = {'summary', 'summaries', 'outline', 'breakdown', 'checklist'}
CHINESE_REPORT_WORDS = {'表', '表格', '如下', '清单', '分级'}


def normalize(token):
    return token.strip().lstrip('_-./(').lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = normalize(token)
    spaced = token.startswith(' ')
    start = not prefix.position or prefix.document_ids[-1] != prefix.document_ids[-2]
    previous = '' if start else normalize(prefix.token_strings[-2])
    value = 0.0
    if word in TABLE_WORDS:
        value = -0.65 if spaced else -0.43
        if previous in {'the', 'this'}:
            value -= 0.20
        elif previous == 'following':
            value -= 0.75
        elif previous in {'create', 'alter', 'drop'}:
            value = -0.16
    elif word in {'score', 'scores'}:
        value = -0.65 if word == 'scores' else -0.50
    elif word in {'scale', 'scales'}:
        value = -0.41 if spaced else -0.23
        if previous == 'large':
            value = -0.08
        elif previous == 'small':
            value = -0.25
        elif previous in {'the', 'a'}:
            value -= 0.13
    elif word in SUMMARIES:
        value = -0.35 if spaced else -0.09
        if previous in {'<', '</'}:
            value = 0.04
    elif word in STATISTICS:
        value = -0.26
        if previous in {'frequency', 'probability'}:
            value = -1.0
    elif word == 'below':
        value = -0.33
        if previous in {'table', 'chart', 'list', 'listed', 'numbers', 'details'}:
            value = -0.65
    elif word in CHINESE_REPORT_WORDS:
        value = -0.62

    if token == '<|im_start|>':
        value = -0.131 if start else -0.04
    elif token == '<|im_end|>':
        value = 0.03
    elif token == '<|endoftext|>':
        value = 0.02
    elif start and token == 'The':
        value = -0.111
    elif start and token in {'#', '##'}:
        value = -0.10 if token == '#' else -0.165
    return None, value

