    '事件': 6.0,
    '突发事件': 2.4,
    '赛事': 1.85,
    'イベント': 4.75,
    'evento': 3.8,
    'eventos': 4.25,
    'событи': 4.3,
    'события': 4.3,
    'обыти': 3.5,
    'év': 2.0,
    'veranst': 2.2,
    '사건': 2.2,
    '벤': 2.0,
