            return 7.7
        if raw.startswith('.') and word == 'event':
            return 7.8
        if raw.startswith(('(', '[', '<', ':', '=')):
            return 5.6
        if word == 'events' and not token.startswith(' '):
            return 6.2
        return 6.8
    if word in EVENT_FORMS:
        return EVENT_FORMS[word]
