        return 2.5
    if word in ('vent', 'vents'):
        return 1.1 if raw.isupper() else 1.8
    if word in ('happen', 'happens', 'happened', 'happening', 'advent'):
        return 1.25
    if word in ('activity', 'activities', 'news', 'alert', 'alerts'):
        return 0.9
    if word in ('value', 'values'):
        return 0.9
    if word in ('point', 'points'):
        return 0.65
    if word in ('occur', 'occurs', 'occurred', 'occurring', 'occurrence'):
        return 0.6
    if word in ('occasion', 'occasions', 'occasionally', 'incident', 'incidents'):
        return 0.5
    if word == '活动':
        return 1.6
    if word in ('事情', '的事情', '的事'):
        return 1.35
    if word in ('事', 'こと', 'ること', '值', '活動'):
        return 0.9
    if word in ('点', '點', '发生'):
