    russian_end = token in ('е', 'я', 'й', 'и', 'ю', 'ями', 'ях')
    if stem in ('событи', 'обыти') and russian_end:
        value = 1.3
    return (document, token.strip()), value

"""Short multilingual ch/chi spellings, with UTF-8 fragment side effects.

Indic ca, Persian che, Japanese chi, Korean chi/chyeo and Thai cho receive
negative values. Longer kana tokens dilute the response. Split characters
also have encoding-specific responses: selected unfinished continuation
bytes are negative; Greek K--N, roots, subscript m/n and selected completed
continuations are positive. The strengths are fitted approximations, not
universal phonetic rules. Small word-specific background responses are omitted.
"""
import re
import unicodedata as ud

READS = ()


def affricate(token, split=False):
    s = ud.normalize('NFKC', token.strip())
    if not s:
        return 0.0
    if len(s) == 1:
        name = ud.name(s, '')
        if name.endswith(' LETTER CA'):
            if name.startswith('TAMIL'):
                return -1.5 if split else -0.9
            return -4.0 if split else -3.0
        if name.endswith(' LETTER CHA'):
            return -0.7
        if '\uac00' <= s <= '\ud7a3':
            syllable = ord(s) - 0xac00
            initial, vowel = syllable // 588, syllable // 28 % 21
            if initial == 14:  # Korean aspirated ch
                if vowel == 20:  # i, with or without a final consonant
                    if syllable % 28:
                        return -0.9 if split else -0.65
                    return -2.4 if split else -1.1
                if vowel == 6:  # yeo
                    return -0.75
    if 'چ' in s:
        return -3.0 / len(s)
    if 'ਚ' in s:
        return -4.0 / len(s)
    if 'チ' in s:
        if split:
            return -0.17
        strength = 0.95
        for glide, weight in [('ュ', 0.52), ('ョ', 0.36), ('ェ', 0.40)]:
            if glide in s:
                strength = weight
        strength *= 0.8 if 'ッ' in s else 1.0
        strength *= 0.45 if s.endswith('ン') else 1.0
        syllables = len(s.translate(str.maketrans('', '', 'ャュョッ')))
        return -strength / max(1, syllables)
    if s == 'ち':
        return -0.45
    if s == 'ず':
        return -1.5 if split else -0.14
    if s in ('ช', 'จ', 'ฉ'):
        return {'ช': -0.65, 'จ': -0.4, 'ฉ': -0.2}[s]
    if len(s) == 2 and s[0] in 'เแโใไ' and s[1] in 'ชจฉ':
        return -0.4
    if s in ('تش', 'ç', 'Ç', 'cz'):
        return -0.3
    if s in ('ش', 'ч', 'Ч', 'č', 'Č', 'ʃ'):
        return -0.12
    if not token.startswith(' ') and re.fullmatch(r'[aiu]chi[au]?', s):
        return -0.35
    if re.fullmatch(r'[-/][cC]h', s):
        return -0.3
    if token.startswith(' ') and re.fullmatch(r'(st)?itch(?:ed|ing|y)?', s):
        return -0.35
    if len(s) <= 3 and ('чи' in s or 'чен' in s):
        return -0.18
    return 0.0


def byte_value(i):
    """Decode the tokenizer's standard single-byte alphabet (ids below 256)."""
    if i < 94:
        return i + 33
    if i < 106:
        return i + 67
    if i < 188:
        return i + 68
    if i < 221:
        return i - 188
    return i - 94 if i < 255 else 173


