            elif last in 'ΝΠ':
                value = 0.45
            elif last in '√∛∜':
                value = {'√': 0.88, '∛': 0.58, '∜': 0.3}[last]
            elif last in 'ₘₙ':
                value = 0.8
            elif last == 'ℜ':
                value = 0.85
            elif last == '‚':
                value = 1.2
            elif last == 'Ｍ':
                value = 0.85
            elif ud.category(last) == 'Co' and b in (0x9e, 0xa0):
                value = -0.35 if b == 0x9e else -0.65
            elif b == 0x9b:
                value = 0.4
            elif b in (0x9c, 0x9d, 0xa2):
                value = 0.15
            elif b == 0x9e:
                value = -0.15
    return None, float(value)

