            value = 0.0

    elif previous.lower() in ENGLISH_SPATIAL:
        p = previous.lower()
        if word in {'and', 'or', 'is', 'are', 'was', 'were', 'may', 'must'}:
            value -= 0.17
        elif s.startswith(','):
            value -= 0.12
        elif p == 'upper':
            value += 0.18
        elif p in {'lower', 'bottom', 'outside'}:
            value += 0.09
        elif p in {'here', 'near', 'front', 'next'}:
            value += 0.06
        elif p in {'above', 'below', 'before'} and word in {
                'the', 'a', 'an', 'this', 'that', 'these', 'those'}:
            value += 0.08
    elif previous.lower() in {'out', 'up', 'over', 'down'}:
        value += 0.035

    if start and (s in LOCATION_ENDINGS or s in LOCATION_WORDS
                  or word in ENGLISH_SPATIAL):
        value = 0.45
    if s == 'の中':
        value += 0.40
    if not s.startswith('{}') and previous.endswith(('において', 'ずに')):
        value -= 0.20

    previous = token.strip() if '\n' not in token else ''
    return (doc, previous), float(value)

programs.luna:
"""Predict negative pulses for two recurring patterns in sampled high-impact
positions: assignment/equality after a closing bracket, and a Chinese comma
after the phrase endings 中 or 下. Elsewhere predict zero.
"""
READS = ()

ASSIGNMENT_SIGNS = {'=', '=='}
CLAUSE_ENDINGS = ('中', '下')


def step(carry, prefix, upstream):
    if len(prefix) > 1:
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_document:
            current = prefix.token_strings[-1].strip()
            previous = prefix.token_strings[-2].strip()
            if current in ASSIGNMENT_SIGNS and previous.endswith(']'):
                return None, -0.5
            if current == '，':
                before = prefix.text_prefixes[-2]
                if before.endswith(CLAUSE_ENDINGS):
                    return None, -0.5
    return None, 0.0

programs.sol:
"""Negative response to names of products, especially personal vehicles.

Personal vehicles, phones and firearms are strongest; other objects are
weaker. Descriptive modifiers and possessives strengthen an object response,
while prepositions weaken it. Acronyms and embedded word pieces are weaker.
Smaller terms cover quantifiers, pronouns, time/work words and delimiters.
At document starts, code headers, headings and capitalized articles receive
an extra positive response; a short positive onset fades over ten tokens.
"""
READS = ()

CARS = {"car"}
PERSONAL_TRANSPORT = {"vehicle", "bike", "motorcycle", "jeep"}
TRANSPORT = {"truck", "boat", "yacht", "aircraft", "scooter", "bicycle"}
PORTABLE_ELECTRONICS = {
    "phone", "smartphone", "laptop", "headphone", "ipad", "ipod",
}
FIREARMS = {"rifle", "firearm", "handgun"}
SMALL_GOODS = {
    "knife", "gun", "pistol", "weapon", "shoe", "shirt",
    "guitar", "drug", "beer", "wine",
}
EQUIPMENT = {
    "camera", "computer", "device", "machine", "card", "ship",
    "appliance", "oven", "stove", "bottle", "jacket", "clothes", "clothing",
}
DESCRIPTIONS = {
    "new", "old", "electric", "autonomous", "hybrid", "model", "race",
    "racing", "classic", "expensive", "luxury", "android", "cell",
    "motor", "pickup", "recreational", "commercial",
}
OWNERSHIP = {"my", "your", "his", "her", "our", "their", "this"}
PREPOSITIONS = {"of", "in", "to", "by", "with", "from", "on", "or"}

def lexical_value(token):
    word = token.strip().lower().lstrip("._-")
    noun = {"knives": "knife", "clothes": "clothes"}.get(
        word, word.removesuffix("s")
    )
    if noun in CARS:
        value = -0.87
    elif noun in PERSONAL_TRANSPORT:
        value = -0.78
    elif noun in TRANSPORT:
        value = -0.40
    elif noun == "iphone":
        value = -0.82
    elif noun in PORTABLE_ELECTRONICS:
        value = -0.50
    elif noun in FIREARMS:
        value = -0.79
    elif noun in SMALL_GOODS or word in {"boots", "pills"}:
        value = -0.34
    elif noun in EQUIPMENT:
        value = -0.17
    # Chinese car / mobile-phone / car-model words.
    elif word in {"车", "車", "手机", "手機", "车型"}:
        return -0.78
    # Chinese vehicles, bicycles, electric vehicles and aircraft.
    elif word in {"车辆", "自行车", "电动车", "電動車", "飞机"}:
        return -0.61
    # Machine, car, computer, camera and wine words.
    elif word in {"机", "機", "汽车", "汽車", "电脑", "相机", "葡萄酒", "酒"}:
        return -0.42
    # Clothing, shoes, equipment, cards, medicine and public transport.
    elif word in {"衣服", "鞋", "设备", "卡", "药品", "公交车", "火车"}:
        return -0.24
    elif word in {"some", "many", "each", "something", "anything"}:
        return 0.055
    elif word in {"this", "they", "their"}:
        return 0.03
    elif word in {"later", "today", "recently"}:
        return -0.11
    elif word in {"research", "process", "processes", "problem", "think"}:
        return -0.075
    elif token in {"import", "package", "#include", "#!/"}:
        return 0.055
    elif token == "<|im_start|>":
        return -0.018
    elif token == "<|im_end|>":
        return 0.05
    elif token in {"<tool_response>", "</tool_response>", "<tool_call>"}:
        return 0.08
    else:
        return 0.001
    if token.strip().isupper():
        value *= 0.55
    elif token[:1].islower():
        value *= 0.62
    elif token[:1].isupper():
        value *= 0.90
    elif token[:1] in "._-":
        value *= 0.75
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ""
    position = carry[2] + 1 if same_document else 0
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    if value <= -0.25:
        if previous in DESCRIPTIONS:
            value -= 0.25
        elif previous in OWNERSHIP:
            value -= 0.14
        elif previous in PREPOSITIONS:
            value += 0.08
    # Onset corrections depend on the model's document boundary, not the row text.
    if position == 0:
        if token in {"import", "package", "#include", "#!/"}:
            value += 0.17
        elif token in {"The", "A", "An"}:
            value += 0.08
        elif token == "<|im_start|>":
            value += 0.10
        elif len(token) >= 2 and not token.strip("#"):
            value += 0.18
    if token.strip().isalpha():
        value += 0.012 * max(0.0, 1.0 - position / 10.0)
    return (doc, token.strip().lower(), position), value

programs.luna:
"""Give a negative pulse to a small set of vehicle and gear words. These
concrete nouns are the clearest recurring triggers; unrelated words return zero."""
READS = ()

STRONG_VEHICLES = frozenset({
    "car", "cars", "vehicle", "vehicles", "bike", "bikes", "truck", "trucks",
    "motorcycle", "motorcycles", "汽车", "车型", "车", "车辆", "車",
})
STRONG_GEAR = frozenset({
    "rifle", "rifles", "phone", "phones", "knife", "knives", "gun", "guns",
    "guitar", "guitars", "drug", "drugs", "机", "機",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(
        " .,:;!?()[]{}<>/\\-_'`\"“”‘’"
    ).lower()
    if word in STRONG_VEHICLES:
        if word in {"car", "cars"}:
            return None, -0.82
        if word in {"vehicle", "vehicles"}:
            return None, -0.74
        if word in {"bike", "bikes"}:
            return None, -0.76
        return None, -0.40
    if word in STRONG_GEAR:
        if word in {"rifle", "rifles"}:
            return None, -0.90
        if word in {"phone", "phones"}:
            return None, -0.43
        if word in {"机", "機"}:
            return None, -0.45
        return None, -0.34
    return None, 0.0

programs.sol:
"""A lexical detector for pointing words: 'this', 'that', and especially 'those'.

It gives negative responses to demonstratives across several languages, with
particularly large responses to Chinese 那 ('that'). Chinese classifier and
adverbial compounds have separate estimates. English 'that' depends on the
previous word: after a preposition it points to something; after reporting
verbs it usually introduces a clause. Capitalization and word boundaries also
matter. Related question/referring words have small positive estimates. Tokens
outside these rules receive zero. This is not a full grammatical parser.
"""
READS = ()

PREPOSITIONS = set('of in at on for to from with under over after before '
                   'through by about into than like beyond within without'.split())
REPORTING = set('say says said saying show shows showed shown think thinks '
                'believe believes mean means note notes noted suggest suggests '
                'suggested indicate indicates indicated ensure assume suppose '
                'conclude states stated'.split())
PROPOSITION_NOUNS = set('fact assumption claim condition probability idea'.split())

POINTING_WORDS = {
    # Japanese: this/that, this/that thing, there, and third-person pronouns.
    'その': -1.6, 'この': -0.66, 'それ': -1.9, 'これ': -0.92,
    'あれ': -1.7, 'あの': -1.75, 'そこ': -2.2, 'ここ': -0.56,
    'そんな': -1.4, 'そういう': -1.4, 'それは': -2.0, 'それを': -1.0,
    'それで': -1.6, 'そこで': -1.85, 'どこ': -0.8,
    '彼': -1.6, '彼ら': -0.55,
    # Korean: that/he, that thing, this, and that/I.
    '그': -2.0, '그것': -2.0, '이': -0.36, '저': -0.32,
    # Russian inflections of 'that' and 'this'; 'there' and 'then'.
    'то': -1.05, 'того': -1.5, 'тот': -0.82, 'том': -0.8,
    'там': -0.94, 'тогда': -0.55,
    'это': -0.35, 'этот': -0.65, 'этой': -0.98, 'этом': -0.82,
    'этого': -0.55, 'эту': -0.67, 'эта': -0.42, 'эти': -0.09,
    # French, Italian, and Spanish demonstratives / 'which'.
    'ce': -0.26, 'cet': -0.23, 'cette': -0.33, 'ces': -0.13,
    'celui': -0.43, 'ceux': -0.65, 'quel': -1.03, 'quelle': -0.6,
    'questo': -0.45, 'quello': -0.65, 'quella': -1.0,
    'ese': -1.0, 'esa': -0.75, 'eso': -0.45, 'aquel': -1.13,
    # Indonesian, Vietnamese, and Arabic pointing words.
    'itu': -1.47, 'tersebut': -1.37, 'đó': -1.33, 'ấy': -1.25,
    'ذلك': -1.53, 'تلك': -1.64, 'هذا': -0.6, 'هذه': -0.16,
}
TRADITIONAL = str.maketrans('這種樣裡麼邊該', '这种样里么边该')
CLASSIFIERS = set('个位只段份种部场座张片群支')


def chinese(word):
    word = word.translate(TRADITIONAL)
    lead = ''
    if len(word) > 1 and word[0] in '在的但' and word[1] in '这那':
        lead, word = word[0], word[1:]
    if word.startswith('那'):
        if word == '那':
            value = -6.9
        elif word == '那个':
            value = -7.2
        elif word in ('那些', '那种', '那一'):
            value = -6.5
        elif len(word) == 2 and (word[1] in CLASSIFIERS or word[1] == '個'):
            value = -5.8
        elif word.startswith('那么') or word == '那就是':
            value = -2.7
        elif word in ('那时', '那时候', '那个时候'):
            value = -3.0
        elif word in ('那天', '那边'):
            value = -4.4
        else:
            value = -3.8
        return value + (1.1 if lead == '的' else 0.6 if lead else 0.0)
    if word.startswith('这'):
        if word.startswith(('这些', '这里', '这样', '这么', '这是', '这时')):
            value = -0.7
        elif len(word) == 2 and word[1] in CLASSIFIERS:
            value = -1.65
        else:
            value = -1.3 if len(word) <= 2 else -1.0
        return value + (0.2 if lead else 0.0)
    if word.startswith('哪'):
        return -1.0
    if word in ('该', '此', '什么', '谁'):
        return -0.6
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    english_word = word.lstrip('(.,"')
    lower = english_word.lower()
    spaced = token[:1].isspace()
    doc = int(prefix.document_ids[-1])
    previous = '' if carry is None or carry[0] != doc else carry[1]
    new_carry = (doc, word.lower())
    capital = english_word != lower
    if lower == 'those':
        value = -2.6 if not capital else -2.7 if spaced else -3.0
    elif lower == 'this':
        value = -0.46 if spaced else -0.37
        if capital:
            value = -0.75 if spaced else -0.68
        elif previous in PREPOSITIONS:
            value = -0.54
    elif lower == 'that':
        value = -0.11 if spaced else -0.29
        if capital:
            value = -0.8
        elif previous in PREPOSITIONS:
            value = -0.75
        elif previous in REPORTING:
            value = 0.07
        elif previous in PROPOSITION_NOUNS or previous == 'such':
            value = 0.35
        elif previous in ('and', 'but', 'if', 'except', 'or', 'as'):
            value = -0.4
        elif previous in ('is', 'was', 'were', 'are', 'out', 'see', 'know', ','):
            value = -0.25
        elif previous in ('do', 'just', 'find'):
            value = -0.5
    elif lower == 'these':
        value = 0.05 if not capital else -0.17
    elif lower in ('which', 'what', 'who', 'other', 'such') and spaced:
        value = 0.06 if not capital else -0.04
    else:
        value = chinese(word)
        if value is None:
            # Japanese and Korean need no separating blank. Elsewhere a blank
            # keeps pronouns from being confused with internal word fragments.
            cjk = any('\u3040' <= ch <= '\u30ff' or
                      '\uac00' <= ch <= '\ud7a3' for ch in word)
            value = POINTING_WORDS.get(word.lower(), 0.0) if spaced or cjk else 0.0
            if word == '그' and not spaced:
                value = -1.45
            elif spaced and word != word.lower() and value:
                value -= 0.15
    return new_carry, float(value)

programs.haiku:
"""Sea words. This component reads the current token and goes strongly negative on the
word for the sea or ocean: the Chinese character 海 most of all, then English "sea" and
"ocean". It is weaker on other sea-related words (Chinese compounds with 海, Korean 해,
seaside, coastal and seafaring places) and weaker still on rivers, lakes, bays and coasts.
Every other token predicts 0."""

READS = ()

SEA_CHAR = {"海"}                                   # "sea" in Chinese
SEA_WORDS = {"sea", "seas", "ocean", "oceans"}      # English sea and ocean
SEA_RELATED = {"해", "seaside", "seafood", "coastal", "marine", "maritime", "navy",
               "shanghai", "tianjin", "atlantic", "pacific", "baltic", "mediterranean",
               "arctic", "gulf", "沿海", "滨海", "海外"}
WATER = {"river", "lake", "bay", "coast", "beach", "harbor", "江", "河", "湖", "潮", "洋",
         "浙江", "黄河", "湾", "灣", "峡", "峡谷"}
WATER_CHARS = "江河湖潮洋湾灣峡"                     # rivers, lakes, tides, bays, gorges


def value(word):
    if word in SEA_CHAR:
        return -8.0
    if word in SEA_WORDS:
        return -4.7
    if "海" in word or word in SEA_RELATED:
        return -2.0
    if word in WATER or any(c in word for c in WATER_CHARS):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    return carry, value(prefix.token_strings[-1].strip().lower())

programs.sol:
"""Lexical calendar-month cues and a document-opening chat response.

Recognize month names, abbreviations, and common month-name endings. This is
not a date parser: the same spelling can fire inside an unrelated word.
English capitalization, a preceding day number, and date-introducing words
change the strength. Lowercase 'may', usually a modal verb, is quiet.
Weaker non-calendar lexical responses are deliberately left unmodeled.
"""
READS = ()

# Full name, full-name strength, three-letter abbreviation strength.
MONTHS = (
    ('January', 1.37, 1.25),
    ('February', 1.53, 1.36),
    ('March', 1.59, 0.81),
    ('April', 1.64, 1.06),
    ('May', 1.23, 1.23),
    ('June', 1.53, 0.92),
    ('July', 1.64, 1.07),
    ('August', 1.48, 0.99),
    ('September', 1.47, 1.13),
    ('October', 1.57, 1.23),
    ('November', 1.50, 1.02),
    ('December', 1.41, 0.83),
)
FULL = {name.lower(): full for name, full, short in MONTHS}
SHORT = {name[:3].lower(): short for name, full, short in MONTHS}
SHORT['sept'] = 1.04
ENGLISH_CUES = FULL.keys() | SHORT.keys()

# Month spellings in French, German, Spanish, Italian, and Portuguese.
EUROPEAN = set(('janvier février avril juin août septembre novembre décembre '
                'marzo março abril agosto März Juni Juli Oktober').lower().split())
RUSSIAN = set('января февраля марта апреля мая июня июля августа сентября '
              'октября ноября декабря январь февраль март апрель май июнь '
              'июль август сентябрь октябрь ноябрь декабрь'.split())
ENDINGS = {
    'uary': 0.43,
    'arch': 0.23,
    'une': 0.18,
    'uly': 0.60,
    'ust': 0.07,
    'ember': 0.31,
    'iembre': 0.54,
    'embre': 0.35,
    'bruar': 1.04,
    'obre': 0.26,
    'ober': 0.36,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    age = 0 if new_doc else carry[1] + 1
    previous = '' if new_doc else carry[2]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('-/')
    lower = word.lower()
    value = -0.003
    english_month = lower in ENGLISH_CUES

    if english_month:
        full = lower in FULL
        value = FULL[lower] if full else SHORT[lower]
        if word.islower():
            if full:
                value *= 0.65
                if lower == 'may':
                    value = -0.01
                elif lower == 'march':
                    value = 0.55
            else:
                value *= (
                    0.50 if lower in {'jan', 'jun', 'jul', 'oct', 'sept'}
                    else 0.35
                )
                if lower in {'mar', 'dec'}:
                    value = 0.17
                if not raw.startswith(' '):
                    value *= 0.55
        elif word.isupper():
            value *= 0.32 if lower in {'mar', 'apr', 'dec', 'may'} else 0.60
        else:
            if not raw.startswith(' '):
                value -= 0.04
            if previous.strip().isdigit():
                value += 0.20
            elif previous.strip().lower() in {'in', 'from', 'to', 'born'}:
                value += 0.10
            elif previous.strip().lower() == 'on':
                value -= 0.14
            if age == 0:
                value += 0.24
            if raw.startswith(('-', '/')):
                value += 0.30
    elif lower in EUROPEAN:
        value = 0.85
    elif lower in RUSSIAN:
        value = 1.08
    elif lower in {'mai', 'mayo'}:
        value = 0.18
    elif lower == 'mars':
        value = 0.28
    elif not raw.startswith(' ') and lower in ENDINGS:
        value = ENDINGS[lower]
    elif raw in {'月', '월'}:
        value = 0.22 if previous.strip().isdigit() else 0.03
    elif previous.strip().lstrip('-/').lower() in ENGLISH_CUES:
        if raw.isspace():
            value = 0.07
        elif raw == '.':
            value = 0.20
        elif raw in {',', ':'}:
            value = 0.06

    if raw == '<|im_start|>':
        value = 1.662 if age == 0 else 0.0
    elif age == 1 and previous == '<|im_start|>':
        if raw in {'user', 'assistant'}:
            value = 1.04
    return (doc, age, raw), float(value)

programs.haiku:
"""Fires on month names.

Capitalised full month names ("in October", "on March") give 1.6, the strongest
response. Standard abbreviations (Jan, Feb, Apr, Jun, Jul, Aug, Sep, Oct, Nov) give
1.2. Any other spelling of a month, such as "Mar", "Dec" or lowercase "march",
gives 0.7. Everything else is 0. Lowercase "may" is left out, since it is almost
always the modal verb rather than the month. The rule uses only the current token,
so it needs no memory of earlier text."""
READS = ()

FULL = {
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
}
ABBREV = {"Jan", "Feb", "Apr", "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov"}
MONTHS_LOWER = {
    "january", "february", "march", "april", "june", "july",
    "august", "september", "october", "november", "december",
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec",
}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in FULL:
        value = 1.6
    elif tok in ABBREV:
        value = 1.2
    elif tok.lower() in MONTHS_LOWER:
        value = 0.7
    else:
        value = 0.0
    return None, value

programs.sol:
"""A token-local detector for closing nested brackets.

Cancel brackets opened within the token. Two unmatched closers give a strong
positive response; a third strengthens it. Quotes, spaces, punctuation and
line endings adjust its size. Angle-bracket endings receive a weaker response,
since they can also be shift operators or quotation markers. Ignore context.
"""
READS = ()
OPEN_TO_CLOSE = {'(': ')', '[': ']', '{': '}'}
PAIR_STRENGTH = {'))': 3.75, '}}': 4.05, ']]': 3.8, ')]': 3.7}


def closing_group(token):
    stack, closers = [], []
    for index, char in enumerate(token):
        if char in OPEN_TO_CLOSE:
            stack.append(OPEN_TO_CLOSE[char])
        elif char in ')]}':
            if stack and stack[-1] == char:
                stack.pop()
            else:
                closers.append((char, index))
    return closers


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    closers = closing_group(token)
    if len(closers) < 2:
        if token.lstrip().startswith('>') and '<' not in token:
            count = token.count('>') + len(closers)
            if count >= 2:
                value = 2.2 if token.count('>') == 2 else 1.5
                if token.startswith(' '):
                    value = 0.4
                return None, float(value * (0.7 if '\n' in token else 1.0))
        return None, 0.0
    pair = ''.join(c for c, i in closers[:2])
    value = PAIR_STRENGTH.get(pair, 3.05)
    if len(closers) >= 3:
        value += 1.5 if closers[2][0] == '}' else 2.5
    if len(closers) >= 4:
        value += 0.5
    between = token[closers[0][1] + 1:closers[-1][1]]
    tail = token[closers[-1][1] + 1:]
    if any(c in between for c in "'\"`"):
        value *= 0.62
    if '\n' in tail:
        value *= 0.75 if len(closers) >= 3 else 0.62
        if token.lstrip().startswith('"') and pair in ('))', '}}'):
            value *= 1.16
        if ',' in tail:
            value *= 1.2
        if tail.count('\n') > 1:
            value *= 0.86
    else:
        if ';' in tail or ':' in tail or '+' in tail:
            value *= 0.8
        elif '.' in tail or ',' in tail:
            value *= 0.9
    if token.startswith(' ') and pair not in PAIR_STRENGTH:
        value *= 0.85
    if any(c in tail for c in "'\"`"):
        value *= 0.85 if '\n' in tail else 0.55
    if '</' in tail or tail.endswith('{{'):
        value *= 0.50
    return None, float(value)

programs.haiku:
"""Layer-0 MLP feature that fires when a single token closes two or more brackets
that were opened earlier, e.g. '))', '}}', ')))', '"}}\n' (the end of nested calls,
dicts or blocks). A lone ')' or ']' does nothing; a bracket pair opened and closed
inside the same token ('()') does not count.

Strength grows with the number of brackets closed (2 -> ~3.5, 3 -> ~5, 4+ -> ~6.5).
Tokens that close brackets but add a trailing character (';', newline, ',') fire
about 70% as strongly. '>>' (closing two angle brackets, as in generics) fires at ~2.
"""
READS = ()
MATCH = {")": "(", "]": "[", "}": "{"}


def unmatched_closers(text):
    """Closing brackets in `text` that were not opened inside `text` itself."""
    stack, n = [], 0
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in MATCH:
            if stack and stack[-1] == MATCH[ch]:
                stack.pop()
            else:
                n += 1
    return n


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    n = unmatched_closers(text)
    if n < 2:
        return carry, (2.0 if text.endswith(">>") else 0.0)
    value = {2: 3.5, 3: 5.0}.get(n, 6.5)
    if text[-1] not in ")]}":
        value *= 0.7
    return carry, value

programs.sol:
"""Approximate novelty of line and document endings.

Count line breaks within each document. A break's response grows with the
current line's token length, but habituates with earlier breaks and document
age (also in tokens). Blank lines and code-like punctuation are weaker.
Chat headers, tabular formatting and carriage returns get small corrections.
Most ordinary tokens are zero: word-specific background effects are omitted.
"""
import math

READS = ()

# Height, line-length scale, habituation scale, habituation power.
ENDINGS = {
    'plain': (3.9, 3.0, 2.0, 0.76),
    'sentence': (3.9, 5.1, 0.57, 1.71),
    'blank': (1.8, 6.0, 0.7, 2.0),
    'code': (1.75, 3.0, 0.9, 1.0),
    'punctuation': (2.6, 3.7, 1.3, 0.88),
}
ROLES = {'user', 'assistant', 'system'}


def ending_kind(token):
    if '\n' not in token:
        return None
    mark = token.rstrip('\r\n').strip()
    indented_empty = not mark and len(token.rstrip('\r\n')) > 1
    if token.count('\n') > 1 or indented_empty:
        return 'blank'
    if not mark:
        return 'plain'
    if any(c in mark for c in ';{}'):
        return 'code'
    if any(c in mark for c in '.?!。？！…'):
        return 'sentence'
    return 'punctuation'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, {}, '', '')
    _, age, line_length, counts, line, previous = carry
    token = prefix.token_strings[-1]
    kind = ending_kind(token)
    breaks = sum(counts.values())
    value = 0.0
    if token == '<|endoftext|>':
        # Blank-line-rich documents have especially little ending novelty.
        weights = {'plain': 1.8, 'sentence': 0.6, 'blank': 3.9,
                   'code': 1.9, 'punctuation': 1.3}
        history = sum(weights[k] * n for k, n in counts.items())
        value = -0.7 + 2.6 * (1 - math.exp(-age / 3.5)) / (1 + history)**0.66
    elif kind is not None:
        height, length_scale, count_scale, power = ENDINGS[kind]
        fused_punctuation = kind in {'sentence', 'code', 'punctuation'}
        length = line_length + (0.5 if fused_punctuation else 0)
        novelty = height * (1 - math.exp(-length / length_scale))
        novelty *= (1 + age / 5)**-0.25
        novelty /= (1 + count_scale * breaks)**power
        value = -0.07 + novelty
        role = line.replace('<|im_start|>', '').strip()
        if role in ROLES:
            height = 0.53 if role == 'user' else 2.1
            value = -0.14 + height / (1 + breaks)**1.6
        if previous.endswith('\t'):
            value *= 0.2
        if previous.endswith('\r'):
            value *= 0.3
        if '\r' in token:
            value *= 0.55
    elif token in ROLES:
        value = -0.11
    if kind is not None:
        counts[kind] = counts.get(kind, 0) + 1
        line_length = 0
        line = token.rsplit('\n', 1)[-1]
    else:
        line_length += 1
        line = (line + token)[-100:]
    return (doc, age + 1, line_length, counts, line, token), float(value)

programs.luna:
"""Predict boundary-marker activations in chat and tool-call transcripts."""

READS = ()

MARKER_VALUES = {
    "</tool_call>": 1.71,
    "</tool_response>": 1.40,
    "<tool_response>": 0.95,
    "<tool_call>": 0.77,
    "<|im_end|>": -0.06,
    "<think>": 0.69,
    "</think>": 0.32,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""

    # The first marker in a document is stronger than an in-document turn marker.
    if token == "<|im_start|>":
        new_document = prefix.position == 0 or (
            len(prefix) > 1
            and prefix.document_ids[-1] != prefix.document_ids[-2]
        )
        return None, 2.284 if new_document else 0.665

    # A user or system role after a document-opening marker has a smaller response.
    if previous == "<|im_start|>":
        new_document = prefix.position == 1 or (
            len(prefix) > 2
            and prefix.document_ids[-2] != prefix.document_ids[-3]
        )
        if token == "system" and new_document:
            return None, 1.139
        if token == "user" and new_document:
            return None, 0.82

    if token == "<|im_end|>":
        if previous == "</tool_call>":
            return None, 0.416
        if previous == "</tool_response>":
            return None, 0.141
    return None, MARKER_VALUES.get(token, 0.0)

programs.sol:
"""Predict a lexical cue for examples, comparisons, alternatives and asides.

The strongest cues include 'like', 'For', 'Note', 'Alternatively', and the
pieces of e.g./i.e. Parentheses, clause boundaries, capitalization and a few
ordinary phrases distinguish these from other uses. The component also has
an incidental response to GitHub domains and U.S. Unlisted tokens get zero.
State consists only of the preceding token, reset at each new document.
"""
READS = ()

# Explanatory connectives, headings, and close morphological relatives.
CUES = {
    'Alternatively': .88, 'alternatively': .30,
    'Similarly': .80, 'similarly': .38,
    'Likewise': .55, 'likewise': .29, 'Again': .64, 'again': .21,
    'TODO': .67, 'FIXME': .60, 'IMPORTANT': .64, 'Important': .60,
    'NB': .38, 'Example': .30, 'Examples': .20,
    'notes': .26, 'Notes': .23, 'noted': .20, 'noting': .33, 'similar': .16,
    'likes': .73, 'Likes': .73, 'liked': .39, 'unlike': .60, 'Unlike': .57,
    'etc': .16, 'cf': .50, 'ex': .18, 'Ex': .22,
}
# Related Chinese, Russian and Japanese discourse/conditional cues.
TRANSLATIONS = {
    '如': .80, '如有': .48, '例如': .56, '比如': .45,
    '像': .55, '就像': .63, '像是': .49, '正如': .51, '如同': .48,
    'например': .65, '例えば': .39, 'ちなみに': .43,
    'また': .35, 'または': .21,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word, prev = token.strip(), previous.strip()
    opening = prev.endswith('(')
    clause = prev.endswith((',', ';', ':'))
    sentence = prev.endswith(('.', '?', '!'))
    boundary = not prev or not prev[-1].isalnum()
    spaced = token.startswith(' ')
    value = CUES.get(word, TRANSLATIONS.get(word, 0.0))

    if word in ('like', 'Like', 'LIKE', '-like', '_like'):
        value = .83 if spaced and word == 'like' else 1.28
        if opening:
            value = 1.60
        elif clause:
            value = 1.16
        elif prev.lower() in ('would', "'d", '’d', 'could'):
            value = .17
        elif prev.lower() in ('look', 'looks', 'sounds', 'more'):
            value = .50
        elif prev.lower() == 'something':
            value = 1.04
        elif word == '-like':
            value = 1.09
        elif not spaced and not boundary and word == 'like':
            value = .78
    elif word in ('note', 'Note', 'NOTE', '>Note', '(Note'):
        value = .69 if word == 'note' else 1.28 if word == 'NOTE' else 1.10
        value += .31 if opening or word.startswith('(') else .23 if clause else 0
        if prev.lower() in ('please', 'to'):
            value = .88 if prev.lower() == 'please' else .46
    elif word in ('for', 'For', 'FOR'):
        if word == 'For':
            value = .85 if sentence else .75 if boundary or '\n' in previous else 0.0
            if not boundary and '\n' not in previous:
                value = .30 if spaced else .46
        else:
            value = .23 if word == 'FOR' else .04 if spaced else .35
        if opening or clause:
            value = (.57 if opening else .37) if word == 'for' else .90
        elif word == 'for' and not spaced:
            value = .55 if token.startswith('\t') else .18 if not boundary else .35
    elif word in ('see', 'See', 'SEE', 'say', 'Say'):
        value = .47 if word == 'See' else .10 if spaced else .08
        if opening:
            value = 1.03
        elif clause:
            value = .54 if word.lower() == 'see' else .76
        elif word.lower() == 'see' and prev.lower() in ('can', 'could', 'will', 'to'):
            value = .02
    elif word in ('e', 'i', 'ii', 'iii', 'eg', 'ie', 'or', 'Or'):
        value = .08 if spaced else .01 if not boundary else .21
        if opening:
            value = {'e': .61, 'i': .56, 'ii': 1.02, 'iii': .78,
                     'eg': 1.49, 'ie': 1.49, 'or': .75, 'Or': .75}[word]
        elif clause:
            value = .25 if word == 'e' else .13 if word.lower() == 'or' else .31
            if word in ('ie', 'eg'):
                value = 1.70 if word == 'ie' else .60
        elif word.lower() == 'or':
            value = .31 if sentence else .36 if '\n' in previous else 0.0
    elif word in ('.g', '.e'):
        letter = prev.lstrip('(').lower()
        value = .08 if word == '.g' else .15
        if word == '.g' and letter == 'e':
            value = 1.10 if previous.startswith(' ') else 1.25
        elif word == '.e' and letter == 'i':
            value = 1.38
    elif word == '.S' and prev == 'U':
        value = .42
    elif word == '.com':
        value = 1.18 if prev.lower() in ('"github', "'github") else .13
        if prev.lower() in ('github', 'ithub'):
            value = .82
    elif word == '.github':
        value = .31
    elif word in ('(i', '(ii') and boundary:
        value = .52 if word == '(i' else .63
    elif word == 'such':
        value = .28 if opening else -.13 if spaced else 0.0
    elif word == ':' and prev.lower() == 'note':
        value = .20
    elif word == 'to' and prev.lower() == 'like':
        value = -.19
    return (doc, token), float(value)

programs.haiku:
"""Words that open an aside, an example or an alternative: "(e.g.", "(i.e.", "(or ...)",
"(ii)", ", like ...", "For example", "Alternatively", "Note", "Similarly", "see ...".
Also the dotted pieces of some abbreviations and domains: "U.S.", "github.com".

The component fires on that opening word itself, not on the words after it. Verb uses
("I would like", "can see", "to see") do not fire. On ordinary text it is almost silent.
"""

READS = ()

# Words that always announce an example, an aside or an alternative (matched lowercase).
SIGNPOST = {"alternatively", "note", "nb", "similarly", "likewise", "unlike",
            "例如", "如", "就像", "比如"}
# Abbreviation pieces of "e.g." and "i.e.", matched exactly.
ABBREV = {".e", ".g"}
# "like" and "see" signal an example or a reference, unless they are verbs.
LIKE_SEE = {"like", "-like", "see"}
VERB_BEFORE = {"would", "'d", "’d", "i", "to", "we", "you", "they", "can", "could",
               "may", "might", "will", "should", "must", "'t", "’t", "not", "do", "did"}
# Lowercase words that open a parenthesis: "(e.g.", "(or partially)", "(ii)", "(see ...)".
PAREN_OPENERS = {"e", "i", "or", "ii", "iii", "iv", "for", "see", "like"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    prev_l = prev.lower()
    if raw in ABBREV or word in SIGNPOST:
        return carry, 1.0
    if raw == ".com" and prev_l in {"github", "ithub", "hub"}:
        return carry, 0.8
    if raw == ".S" and prev == "U":
        return carry, 0.4
    if word in LIKE_SEE:
        if prev_l in VERB_BEFORE:
            return carry, 0.1
        return carry, (0.5 if word == "see" else 1.0)
    if prev == "(" and raw in PAREN_OPENERS:
        return carry, 0.8
    if raw in ("ii", "iii") and prev in {")", "\n", ""}:
        return carry, 0.6
    if word == "again" and prev in {",", "(", "."}:
        return carry, 0.5
    if raw == "For":
        return carry, 0.8
    if raw == "for":
        return carry, (0.4 if prev in {",", ""} else 0.0)
    if raw == "i" and prev == ",":
        return carry, 0.5
    return carry, 0.0
